  ($s$grant$s$, $s$US Equestrian National Youth Sportsman's Award$s$, $s$US Equestrian (USEF)$s$, $s$https://usef.org/forms-pubs/MxEDBap9pDw/national-youth-sportsmans-award$s$, $s$An award for young riders of any breed or discipline who show sportsmanship, act as role models and help their community. The winner gets a $1,000 grant for an educational program.$s$, $s$Get the application from USEF or your breed or discipline association (it opens May 1), and send it with recommendation letters to that association by August 15. Each association nominates one rider.$s$, $s$$1,000 educational grant (reserve winner $500)$s$, 1000, $s$Opens May 1; due to your affiliate association by August 15$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must be 17 or younger as of December 1 and an active junior member of US Equestrian and a USEF Recognized National Affiliate (such as AQHA, APHA or USHJA).$s$, false),
  ($s$scholarship$s$, $s$Reining Horse Foundation Scholarship$s$, $s$Reining Horse Foundation (National Reining Horse Association)$s$, $s$https://form.jotform.com/253088034792159$s$, $s$At least $30,000 a year goes to 10 high school seniors who are NRHA/NRHyA youth members heading to a 2- or 4-year college or trade school. Financial need, grades and reining involvement are all considered.$s$, $s$Fill out the online application with family income details, your transcript, an essay of up to 500 words, three references (none from relatives) and a headshot. It's due in mid-April of senior year.$s$, $s$$1,500 to $5,000 (three $5,000 awards)$s$, 5000, $s$Due April 15 of senior year (the 2026 deadline was April 15, 2026)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must have been an NRHA member for at least 24 months before applying, with membership still current.$s$, false),
  ($s$scholarship$s$, $s$NSBA Foundation Youth Scholarship$s$, $s$National Snaffle Bit Association Foundation$s$, $s$https://nsba.com/youth-scholarship$s$, $s$A $2,000 scholarship ($1,000 a year for two years) for a National Snaffle Bit Association youth member going to college full time. Grades, test scores and financial need are considered.$s$, $s$Apply online between December 1 and February 1 with your essay and test scores.$s$, $s$$2,000 total ($1,000 a year for 2 years)$s$, 2000, $s$Opens December 1; due February 1$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must be a current NSBA youth member and attend an accredited college full time (12+ credit hours).$s$, false),
  ($s$scholarship$s$, $s$ASHBA Youth Scholarship$s$, $s$American Saddlebred Horse and Breeders Association$s$, $s$https://www.saddlebred.com/about-ashba-giving/grants-scholarships/youth-scholarships$s$, $s$Scholarships for American Saddlebred Horse and Breeders Association (ASHBA) youth members in grade 11 or higher who have financial need and have taken part in ASHBA youth programs.$s$, $s$Send the application, essay, transcripts and tax information between April 15 and July 31.$s$, $s$Amount not stated$s$, null::int, $s$Open April 15 to July 31 each year$s$, $s$US$s$, '{11,12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must be an ASHBA member, 21 or younger, who has taken part in ASHBA youth programs and is committed to the Saddlebred industry.$s$, false),
  ($s$scholarship$s$, $s$United States Pony Clubs College Scholarships$s$, $s$United States Pony Clubs$s$, $s$https://ponyclub.org/activities/college-scholarships$s$, $s$Several $1,000 to $1,500 scholarships for Pony Club members, including the Jubilee, Dorothy Renfro, Triple Crown Nutrition, Bodgie Read and Anson W. H. Taylor awards. The Anson Taylor award is for members entering senior year who are involved in land conservation.$s$, $s$Members apply through the USPC scholarship application and members-only Scholarship Guide on ponyclub.org.$s$, $s$$1,000 to $1,500 depending on the award$s$, 1500, $s$Deadline is in the members-only USPC Scholarship Guide$s$, $s$US$s$, '{11,12}'::int[], 3.0, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a current USPC member. Most awards need a certain Pony Club certification (for example C-1 or C-2 Horse Management or higher) and a 3.0 GPA or better.$s$, false),
  ($s$scholarship$s$, $s$IEA Founders College Scholarship Awards$s$, $s$Interscholastic Equestrian Association$s$, $s$https://www.rideiea.org/wp-content/uploads/2026/05/Founders-Scholarship-Page-2027.pdf$s$, $s$College scholarship money for the top two senior riders in each hunt seat, western and dressage class at the IEA National Finals. In 2027 the total is $25,050.$s$, $s$There's no separate application. Seniors earn the award by placing first or second among seniors in their class at IEA National Finals, and checks are mailed by July 31, 2027.$s$, $s$$250 to $1,100 depending on class and placing$s$, 1100, $s$Awarded at IEA National Finals in spring of senior year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$,$s$Sports$s$]::text[], null::text[], $s$any$s$, null, $s$Must be an IEA team rider who qualifies for and places at IEA National Finals as a senior.$s$, true),
  ($s$scholarship$s$, $s$NRCHA Merit Scholarship$s$, $s$NRCHA Foundation (National Reined Cow Horse Association)$s$, $s$https://www.nrcha.com/foundation/youth-scholarships$s$, $s$A $2,500 scholarship for high school students who are NRCHA members or have a close relative who is a member. It's judged on grades, activities and community service.$s$, $s$Submit the online application by September 30. You can apply every year but win only once.$s$, $s$$2,500$s$, 2500, $s$Due September 30 (the 2026 deadline has passed; look for the 2027 round)$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must be an active NRCHA member, or the close relative of one (parent, guardian, sibling, grandparent, aunt, uncle or cousin).$s$, false),
  ($s$scholarship$s$, $s$Roy Edsall Memorial Scholarship$s$, $s$NRCHA Foundation$s$, $s$https://www.nrcha.com/foundation/youth-scholarships$s$, $s$A $3,000 education grant for students 18 and under who belong to (or are related to a member of) a western horse association such as AQHA, NRHA, NCHA or NRCHA. It looks for horse community involvement, competition and good sportsmanship.$s$, $s$Submit the online application on the NRCHA Foundation page. The 2026 deadline was February 14.$s$, $s$$3,000$s$, 3000, $s$Usually mid-February (the 2026 deadline was February 14, 2026)$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must be 18 or under, be (or be related to) an active member of a western equine association, and have competed at some level.$s$, false),
  ($s$scholarship$s$, $s$AMHA Youth Academic Scholarship$s$, $s$American Miniature Horse Association$s$, $s$https://amha.org/amhya-youth-scholarship$s$, $s$A scholarship for American Miniature Horse Association youth members in their junior or senior year of high school. Academic success is part of the decision, and the money is paid to the school.$s$, $s$Send the application, essay and three character references to the AMHA Youth Coordinator by mail or email by August 31.$s$, $s$Amount not stated$s$, null::int, $s$Due August 31 each year$s$, $s$US$s$, '{11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must have been an AMHA member for at least three years, be 18 or younger and at least a high school junior. Past winners can't apply.$s$, false),
  ($s$scholarship$s$, $s$Georgia High School Rodeo Association Senior Scholarships$s$, $s$Georgia High School Rodeo Association$s$, $s$https://irp.cdn-website.com/a1ba706e/files/uploaded/GHSRA+Contestant_Parent+Handbook+2026_27.pdf$s$, $s$GHSRA seniors can apply for scholarships handed out at the Georgia State Finals rodeo. Seniors who qualify for the National High School Finals Rodeo can also apply for national scholarships.$s$, $s$Watch the GHSRA website, Facebook page and BAND group for the application and deadline. For national scholarships, apply online with NHSRA before Nationals and also turn in paper copies.$s$, $s$Amount not stated$s$, null::int, $s$Posted by GHSRA each spring before State Finals$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$,$s$Sports$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a GHSRA senior member.$s$, false),
  ($s$scholarship$s$, $s$Pinto Heritage Foundation Scholarships$s$, $s$Pinto Heritage Foundation (Pinto Horse Association of America)$s$, $s$https://www.pinto.org/scholarships/current-scholarships$s$, $s$More than a dozen $500 to $1,000 scholarships for high school seniors and college students involved with Pinto horses, ponies or miniatures. Some need a judging background or an agriculture major.$s$, $s$Download the scholarship application from pinto.org and mail it with an essay and three recommendation letters, postmarked by January 15.$s$, $s$$500 to $1,000 a year depending on the award$s$, 1000, $s$Postmarked by January 15 each year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must be enrolled, or have applied to enroll, full time at an accredited school. Involvement with Pinto horses and the Pinto Horse Association counts.$s$, false),
  ($s$scholarship$s$, $s$TWHBEA Industry Scholarships$s$, $s$Tennessee Walking Horse Breeders' and Exhibitors' Association$s$, $s$https://twhbea.com/youth/industry-scholarships/$s$, $s$A set of scholarships worth $11,500 in total for 2026, including the Glenn C. Dowell Family Scholarship, for Tennessee Walking Horse association members (or their families) from junior year of high school on.$s$, $s$Complete the combined TWHBEA scholarship application on the Industry Scholarships page by June 15.$s$, $s$$1,000 awards, plus $6,500 total for the Dowell Family Scholarship$s$, null::int, $s$Due June 15 (the 2026 deadline was June 15, 2026)$s$, $s$US$s$, '{11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$The Dowell Scholarship needs 18 months of TWHBEA membership before the deadline. For some other awards, a family member's membership counts. Must be 24 or younger.$s$, false),
  ($s$scholarship$s$, $s$Alex Mooney Memorial Scholarship$s$, $s$Morgan Horse Foundation (American Morgan Horse Association)$s$, $s$https://morganhorse.com/amhect/grants-scholarships/alex-mooney-scholarship$s$, $s$The Morgan Horse Foundation gives at least $5,000 a year through this award for undergraduate college study or professional development. It's for people in the Morgan horse community.$s$, $s$Download the criteria and application form from the Morgan Horse Foundation page. Applications reopen in spring 2027 and close June 30.$s$, $s$At least $5,000 awarded each year$s$, null::int, $s$Reopens spring 2027; usually due June 30$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$AMHA membership is required for Morgan Horse Foundation awards.$s$, false),
  ($s$scholarship$s$, $s$Animal Welfare Institute Scholarship$s$, $s$Animal Welfare Institute$s$, $s$https://awionline.org/funding-opportunities/animal-welfare-institute-scholarship/$s$, $s$Up to 12 scholarships of $3,000 for U.S. high school seniors who have volunteered for or spoken up for animals and plan a career that reduces animal suffering or protects vulnerable species.$s$, $s$Apply online with a recommendation from a non-family member who knows your animal protection work. Applications are open November 2026 through March 2027.$s$, $s$$3,000$s$, 3000, $s$Open November 2026 through March 2027; winners announced by May 1, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$Must show a record of animal welfare volunteering or advocacy. Finalists must confirm college acceptance before receiving funds.$s$, false),
  ($s$scholarship$s$, $s$USDA 1890 National Scholars Program$s$, $s$U.S. Department of Agriculture$s$, $s$https://www.usda.gov/about-usda/general-information/staff-offices/office-partnerships-and-public-engagement/minority-serving-higher-education-institutions/1890-program/usda-1890-national-scholars-program$s$, $s$Covers full tuition, fees, books, and room and board, plus a paid USDA summer internship. It's for students majoring in agriculture, food or natural resource sciences (including pre-vet animal science) at one of the 19 historically Black 1890 land-grant universities, such as Fort Valley State University in Georgia.$s$, $s$Apply online through the USDA portal with transcripts and two essays. The 2026 round closed March 8, 2026, so watch for the 2027 round.$s$, $s$Full tuition, fees, books, and room and board, renewable for 4 years$s$, null::int, $s$The 2026 deadline was March 8, 2026; the next round usually opens in late fall or winter$s$, $s$US$s$, '{12}'::int[], 3.0, null, 1080, 21, null::int, false, true, array[$s$Agriculture$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must be a U.S. citizen accepted to one of the 19 1890 land-grant universities (in Georgia, Fort Valley State University) and show leadership and community service.$s$, false),
  ($s$scholarship$s$, $s$FVSU 1890 Scholarship Program$s$, $s$Fort Valley State University, College of Agriculture, Family Sciences and Technology$s$, $s$https://fvsu.edu/academics/1890-scholarship-program$s$, $s$Up to $6,000 a year (up to $24,000 total) for incoming students who major in agriculture, family sciences or technology at Fort Valley State and plan careers in food, agriculture or natural resources.$s$, $s$Apply to FVSU with a College of Agriculture, Family Sciences and Technology major, fill out the FAFSA, and submit the FVSU 1890 Scholarship application with an essay. Check the FVSU site for the next application window.$s$, $s$Up to $6,000 a year, up to $24,000 total$s$, 24000, $s$The current window is closed; check FVSU for the next one$s$, $s$GA$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, true, array[$s$Agriculture$s$]::text[], null::text[], $s$four_year$s$, $s$Fort Valley State University$s$, $s$Minimum section scores: SAT 480 reading and writing and 440 math, or ACT 17 English/reading and 17 math. Must enroll full time in an agriculture-college major.$s$, false),
  ($s$scholarship$s$, $s$UGA CAES Rural Scholars Program$s$, $s$University of Georgia College of Agricultural and Environmental Sciences$s$, $s$https://caes.uga.edu/students/scholarships/rural-scholars$s$, $s$$7,000 a year for up to four years for high school seniors from rural Georgia counties who will major in an agriculture or environmental sciences program at UGA. Only four students are chosen each year.$s$, $s$Submit the Rural Scholars online application (resume, essay and recommendation letter) and apply to UGA separately. It's due by 5 p.m. on November 13, 2026.$s$, $s$$7,000 a year, renewable for up to 4 years$s$, 28000, $s$Due 5 p.m. November 13, 2026; interviews February 19-20, 2027$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$]::text[], array[$s$Rural or small-town student$s$]::text[], $s$four_year$s$, $s$University of Georgia$s$, $s$Must be from a rural Georgia county (population 50,000 or less, listed on the page), be admitted to UGA and choose a CAES major. Scholars must keep a 3.0 GPA in college.$s$, false),
  ($s$scholarship$s$, $s$UGA CAES Alumni Association Freshman Scholarships (Prospective Students Scholarship Program)$s$, $s$University of Georgia College of Agricultural and Environmental Sciences$s$, $s$https://www.caes.uga.edu/students/scholarships.html$s$, $s$One application for incoming UGA freshmen who plan to major in an agriculture or environmental sciences program. Students interested in animal science may also be considered for Animal and Dairy Science department awards, some of which favor entering freshmen.$s$, $s$Submit the online Prospective Students scholarship application, which is open July 1 through March 31 of senior year.$s$, $s$Amount not stated$s$, null::int, $s$Accepted July 1 through March 31$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$]::text[], null::text[], $s$four_year$s$, $s$University of Georgia$s$, $s$For incoming first-year (and transfer) CAES students only; current UGA students can't apply.$s$, false),
  ($s$scholarship$s$, $s$ABAC Foundation Scholarships (Stallion, Horizon, Visionary and Baldwin Scholars)$s$, $s$Abraham Baldwin Agricultural College Foundation$s$, $s$https://abac.edu/admissions/abac-scholarships.html$s$, $s$One application covers all ABAC Foundation scholarships at Georgia's agricultural college in Tifton, including tiered awards for incoming freshmen and the top-level Baldwin Scholars award. Awards look at grades, activities and leadership, and some also consider need or where you live.$s$, $s$After you're accepted to ABAC, log in to myABAC and apply through Scholarship Universe. The priority deadline is March 1.$s$, $s$Amount not stated$s$, null::int, $s$Priority deadline March 1$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, $s$Abraham Baldwin Agricultural College$s$, $s$You must be accepted to ABAC before you can open the scholarship application.$s$, false),
  ($s$scholarship$s$, $s$Southwest Georgia Farm Credit Scholarships (including the Duane Watson Scholarship)$s$, $s$Southwest Georgia Farm Credit$s$, $s$https://www.agbizinfo.com/resources/scholarships$s$, $s$Scholarships from a southwest Georgia farm lender for high school seniors going to a 2- or 4-year college, including the $2,000 Duane Watson award for students pursuing an agriculture degree. There is also a $1,500 award for technical or trade programs.$s$, $s$Get the application from Southwest Georgia Farm Credit's scholarship page. The fall-start round was due January 30 in 2026.$s$, $s$$1,500 to $2,000$s$, 2000, $s$Usually due late January of senior year (January 30 in 2026)$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$]::text[], null::text[], $s$any$s$, null, $s$Aimed at students in Southwest Georgia Farm Credit's 21-county service area. The Duane Watson award needs an agriculture-related major; the general award also allows business, accounting or communications.$s$, false),
  ($s$scholarship$s$, $s$Angus Foundation Undergraduate Scholarships$s$, $s$Angus Foundation (American Angus Association)$s$, $s$https://www.angus.org/angus-media/angus-journal/2026/02/2026-angus-foundation-scholarship-applications-open-february-1$s$, $s$More than $190,000 a year in undergraduate and graduate scholarships for Junior Angus members. One online application makes you eligible for all of them.$s$, $s$National Junior Angus Association (NJAA) members apply through AAA Login (Programs tab). Applications open February 1 and were due May 1 in 2026.$s$, $s$Varies; more than $190,000 awarded each year in total$s$, null::int, $s$Opens February 1; due May 1 (2026 dates)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$,$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a Junior Angus (NJAA) member. There is also a separate Vo-Tech scholarship for beef-industry technical training.$s$, false),
  ($s$scholarship$s$, $s$Hereford Youth Foundation of America Scholarships$s$, $s$Hereford Youth Foundation of America$s$, $s$https://hereford.org/youth/njha/scholarship-opportunities/$s$, $s$Scholarships for National Junior Hereford Association members going on to college, including ten $10,000 Vanier Family Scholarships in the fall round and $1,500 to $5,000 awards in the spring round.$s$, $s$Apply online through the foundation's Submittable page. The fall round is due September 1 and the spring round April 15.$s$, $s$$1,500 to $10,000$s$, 10000, $s$Fall round due September 1; spring round due April 15$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$,$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a National Junior Hereford Association (NJHA) member.$s$, false),
  ($s$scholarship$s$, $s$ADGA Scholarship$s$, $s$American Dairy Goat Association$s$, $s$https://adga.org/wp-content/uploads/2026/01/2026-ADGA-Scholarship-Application.pdf$s$, $s$A scholarship for American Dairy Goat Association youth or regular members (family memberships count) who have been accepted to or are enrolled in college.$s$, $s$Email, mail or fax the application with essay answers, your college acceptance letter and transcripts to ADGA by April 1.$s$, $s$Amount not stated$s$, null::int, $s$Due April 1 each year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$,$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a current ADGA member and already accepted to an accredited college.$s$, false),
  ($s$scholarship$s$, $s$National Junior Swine Association Scholarships$s$, $s$National Junior Swine Association (National Swine Registry)$s$, $s$https://nationalswine.com/njsa/njsa-scholarships.php$s$, $s$Several scholarships for young swine exhibitors, including the $1,500 Guy Jackson Memorial Scholarship for high school seniors studying an ag-related field and the $1,000 Zwilling Future Leaders' Scholarship.$s$, $s$Apply through the NJSA scholarship application (essays, recommendation letters and video answers) by April 15.$s$, $s$$1,000 to $1,500$s$, 1500, $s$Due April 15 each year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$,$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$NJSA membership is preferred or encouraged. The Guy Jackson award needs at least two years of showing Durocs at the county, state or national level.$s$, false),
  ($s$scholarship$s$, $s$Foundation Fellowship$s$, $s$University of Georgia (Jere W. Morehead Honors College)$s$, $s$https://honors.uga.edu/scholarships/prospective-students/foundation-fellowship/$s$, $s$UGA's top academic scholarship for high school seniors with very strong records. Fellows get a yearly stipend on top of HOPE/Zell Miller, plus funded travel-study trips, an Oxford summer program, and research grants.$s$, $s$Submit UGA's first-year admission application, then complete the Morehead Honors College/Foundation Fellowship application from your application status page by November 1. Finalists must attend interviews in late February.$s$, $s$Georgia residents: $15,750 a year stipend plus the Zell Miller Scholarship, for four years, plus funded travel-study and research grants (out-of-state students get a larger stipend and a tuition waive$s$, 63000, $s$November 1 each year (the 2026 deadline has passed; next is November 1, 2027 for the class of 2028)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Georgia$s$, $s$Must not have enrolled at another college as a degree-seeking student. The Bernard Ramsey Honors Scholarship was merged into the Foundation Fellowship in 2021. Fellows must live in Myers Hall the first year and keep a 3.40 UGA GPA.$s$, false),
