  ($s$scholarship$s$, $s$Flagship 50 Tuition Match$s$, $s$Oglethorpe University$s$, $s$https://oglethorpe.edu/admission/flagship50/$s$, $s$Oglethorpe caps tuition at your home state's flagship public university rate (UGA for Georgia residents) for qualifying first-year students. Georgia residents can stack HOPE and the Tuition Equalization Grant on top.$s$, $s$No separate application stated: admitted students who meet any one of the academic minimums receive it.$s$, $s$Tuition matched to your home state's flagship rate for four years$s$, null::int, $s$No separate deadline; awarded with admission for fall 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Oglethorpe University$s$, $s$Any ONE of these qualifies: a 3.8 GPA (as calculated by Oglethorpe), a 1400 SAT superscore, or a 30 ACT superscore. Must live on campus for three years. Can't be combined with Oglethorpe's full-tuition scholarships.$s$, true),
  ($s$scholarship$s$, $s$Spelman College Merit Scholarships$s$, $s$Spelman College$s$, $s$https://www.spelman.edu/financial-aid/scholarships/scholarships-for-future-students.html$s$, $s$Admitted first-year students at Spelman, a women's college, are automatically considered for merit awards ranging from half tuition to full tuition, fees, and room and board (including the Dovey Johnson Roundtree Presidential and Dean's Scholarships).$s$, $s$No separate application: your admission application counts as your scholarship application. Some programs (Bonner, UPS, Ralph Lauren) need a separate application.$s$, $s$From half tuition up to full tuition, fees, and room and board for four years$s$, null::int, $s$No separate deadline posted; apply Early Action or Early Decision for Civic Scholar programs$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Woman$s$]::text[], $s$four_year$s$, $s$Spelman College$s$, $s$Considered with or without test scores. Selection looks at GPA, test scores if sent, service, and leadership.$s$, true),
  ($s$scholarship$s$, $s$Jonathan Smith Scholarship$s$, $s$Spelman College$s$, $s$https://www.spelman.edu/financial-aid/scholarships/scholarships-for-future-students.html$s$, $s$A Spelman merit scholarship for students from Georgia, covering tuition, fees, and room and board.$s$, $s$No separate application: admitted students are considered automatically by the Office of Admissions.$s$, $s$Tuition, fees, and room and board for four years$s$, null::int, $s$No separate deadline posted; considered with admission$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Woman$s$]::text[], $s$four_year$s$, $s$Spelman College$s$, $s$For Georgia students.$s$, true),
  ($s$scholarship$s$, $s$Morehouse Academic Scholarship$s$, $s$Morehouse College$s$, $s$https://morehouse.edu/admissions/financial-aid-and-scholarships/scholarships/freshman-merit-based-scholarships/$s$, $s$Merit scholarships that all academically qualified first-time freshmen admitted to Morehouse, a men's college, are automatically reviewed for.$s$, $s$No separate application: admitted students are reviewed automatically. Award emails usually go out early in the new year.$s$, $s$Amount varies; some awards renew for up to four years$s$, null::int, $s$No separate deadline; awarded while funds last, so apply early$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Man$s$]::text[], $s$four_year$s$, $s$Morehouse College$s$, $s$Morehouse is a men's college.$s$, true),
  ($s$scholarship$s$, $s$Clark Atlanta University Merit-Based Scholarship$s$, $s$Clark Atlanta University$s$, $s$https://www.cau.edu/admissions/undergraduate-admissions$s$, $s$First-year applicants to Clark Atlanta with at least a 3.0 unweighted GPA are automatically considered for competitive merit scholarships.$s$, $s$No separate application: apply for admission, ideally by Early Action, with transcripts in by the deadline for priority.$s$, $s$Amount not stated$s$, null::int, $s$Early Action priority November 1 (passed for 2026); final deadline March 1 of senior year$s$, $s$US$s$, '{12}'::int[], 3.0, $s$unweighted$s$, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Clark Atlanta University$s$, $s$Meeting the 3.0 minimum does not guarantee an award.$s$, true),
  ($s$scholarship$s$, $s$Steele Scholarship$s$, $s$Valdosta State University (Langdale College of Business)$s$, $s$https://www.valdosta.edu/scholarships/vsu-scholarship-available.php$s$, $s$A renewable Valdosta State scholarship for incoming business students with strong grades and SAT scores.$s$, $s$Apply through VSU's general scholarship application in Scholarship Universe (2027-28 applications opened October 1, 2026) and file the FAFSA if you want need considered.$s$, $s$Amount not stated; renewable with a 3.25 college GPA$s$, null::int, $s$Most VSU scholarship deadlines fall early in the spring semester; check Scholarship Universe$s$, $s$US$s$, '{12}'::int[], 3.25, null, 1240, null::int, null::int, false, false, array[$s$Business$s$]::text[], null::text[], $s$four_year$s$, $s$Valdosta State University$s$, $s$Requires BOTH a 1240 SAT and a 3.25 high school GPA (4.0 scale). For business majors.$s$, false),
  ($s$scholarship$s$, $s$UWG Honors College Presidential Scholarship$s$, $s$University of West Georgia (Honors College)$s$, $s$https://www.westga.edu/academics/honors/presidential-scholarships.php$s$, $s$A full scholarship for top incoming first-year students in UWG's Honors College, covering tuition, room and board, and fees.$s$, $s$Apply to UWG and to the Honors College by January 15. Highly qualified students are invited to interview, with decisions around March 1.$s$, $s$Tuition, room and board, and fees; renewable for up to three more years$s$, null::int, $s$January 15 of senior year (Honors College application)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of West Georgia$s$, $s$Must be eligible for the Honors College. No published GPA or test minimum.$s$, false),
  ($s$scholarship$s$, $s$Honors College Presidential Scholarship (Columbus State)$s$, $s$Columbus State University (Honors College)$s$, $s$https://www.columbusstate.edu/honors-college/scholarships.php$s$, $s$Columbus State's top Honors College award for entering freshmen. The Honors College also offers Tower ($2,500 a year) and University ($1,000 one-time) scholarships.$s$, $s$Apply to the Honors College by its deadline; admitted applicants who meet the honors requirements are considered automatically.$s$, $s$Up to $5,000 a year for four years, plus a one-time study abroad stipend of up to $3,200$s$, 23200, $s$Honors College application deadline (date not posted; historically late January)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Columbus State University$s$, $s$Must be admitted to the Honors College.$s$, false),
  ($s$scholarship$s$, $s$SCAD Academic and Achievement Scholarships$s$, $s$Savannah College of Art and Design (SCAD)$s$, $s$https://www.scad.edu/admission/financial-aid-and-scholarships/scholarships$s$, $s$Merit scholarships for incoming SCAD students based on academic achievement or overall achievement, considered with the admission application.$s$, $s$Apply to SCAD and send any requested materials to your admission adviser. A portfolio and achievement profile are optional but improve your chances.$s$, $s$Amount not stated; renews with a 3.0 GPA$s$, null::int, $s$No separate deadline posted; considered with admission$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Arts$s$]::text[], null::text[], $s$four_year$s$, $s$Savannah College of Art and Design$s$, null, true),
  ($s$scholarship$s$, $s$SCAD Challenge$s$, $s$Savannah College of Art and Design (SCAD)$s$, $s$https://www.scad.edu/admission/financial-aid-and-scholarships/scholarships$s$, $s$A creative competition for high school juniors and seniors that awards SCAD scholarships.$s$, $s$Enter through SCAD's Challenge page during the school year.$s$, $s$Scholarship amounts not stated$s$, null::int, $s$Check SCAD's Challenge page for this year's dates$s$, $s$US$s$, '{11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Arts$s$]::text[], null::text[], $s$four_year$s$, $s$Savannah College of Art and Design$s$, null, false),
  ($s$scholarship$s$, $s$GGC Top Honors Scholarship$s$, $s$Georgia Gwinnett College$s$, $s$https://www.ggc.edu/admissions/financial-aid/scholarships-and-grants/$s$, $s$A limited award for strong incoming first-year students who are accepted early and admitted to GGC's Honors Program.$s$, $s$No application needed: be accepted to GGC by December 1 and admitted to the Honors Program. A committee picks recipients, with priority to early applicants.$s$, $s$$1,000 a year$s$, null::int, $s$Be accepted by December 1 of senior year; fall entry only$s$, $s$US$s$, '{12}'::int[], 3.5, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Georgia Gwinnett College$s$, $s$Uses the high school core GPA. Limited number of awards. Must be admitted to the Honors Program.$s$, true),
  ($s$scholarship$s$, $s$Young Harris College Merit Scholarships$s$, $s$Young Harris College$s$, $s$https://www.yhc.edu/financial-aid/$s$, $s$Every new Young Harris student is considered for one of four merit scholarship tiers.$s$, $s$Apply for admission; all new students are considered for merit awards.$s$, $s$$16,000 to $20,000 a year, depending on tier$s$, null::int, $s$No separate deadline posted; considered with admission$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Young Harris College$s$, $s$Tier criteria are not published; contact the financial aid office.$s$, true),
  ($s$grant$s$, $s$Zell Miller Grant$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/hope-zell-miller-grants/zell-miller-grant/$s$, $s$Pays full standard tuition for Georgia residents in a technical certificate or diploma program at a TCSG or USG school. No high school GPA or test score is needed to start, but students must keep a 3.5 college GPA.$s$, $s$Complete the FAFSA or Georgia's state aid application (GSFAPPS) on GAfutures and enroll in an eligible certificate or diploma program. The college checks eligibility; the first term is paid back retroactively if you have a 3.5 GPA at the end of it.$s$, $s$Full standard undergraduate tuition at the school you attend (up to 15 hours per term)$s$, null::int, $s$Apply before or during the term you enroll; ask your college's financial aid office for its cutoff$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], null::text[], $s$technical$s$, null, $s$Must be a Georgia resident in a certificate or diploma program (not a degree program) and keep a 3.5 cumulative college GPA. Not available for dual enrollment. Grant hours are capped at 63 semester hours.$s$, false),
  ($s$grant$s$, $s$HOPE Career Grant$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/hope-zell-miller-grants/hope-career-grant/$s$, $s$Extra money on top of the HOPE Grant or Zell Miller Grant for students in high-demand technical programs, such as welding, nursing-related fields, truck driving and law enforcement. It helps pay costs beyond tuition.$s$, $s$Enroll in an eligible program at a Georgia technical college and qualify for the HOPE Grant; the award is added for each eligible term. Ask your college's financial aid office to confirm your program is on the list.$s$, $s$$125 to $500 per term for most programs; up to $1,100 for truck driving and up to $3,750 for basic law enforcement$s$, 3750, $s$Paid each term you are enrolled in an eligible program$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Trades$s$]::text[], null::text[], $s$technical$s$, null, $s$Must be receiving the HOPE Grant or Zell Miller Grant and be enrolled in a program on the state's high-demand career list. Not available for dual enrollment.$s$, true),
  ($s$grant$s$, $s$Dual Enrollment$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/dual-enrollment/$s$, $s$Lets Georgia high school students take college classes for free while still in high school, earning both high school and college credit. It covers tuition, mandatory fees and required books for approved courses.$s$, $s$Get admitted to a participating Georgia college, then complete the Dual Enrollment funding application on GAfutures with your high school counselor and the college. Apply before each term.$s$, $s$Free tuition, mandatory fees and required books, up to 30 semester hours total (15 hours per term)$s$, null::int, $s$Before each term; check the college's dual enrollment deadline$s$, $s$GA$s$, '{10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$9th graders are not eligible. 10th graders may only take approved career (CTAE) courses at a technical college, or any approved course if they have a 1200 SAT or 26 ACT. 11th and 12th graders may take any approved course. Must attend an eligible Georgia public or private high school or home study program. Funding stops at 30 semester hours, and withdrawing from two courses ends eligibility.$s$, false),
  ($s$grant$s$, $s$Accelerated Career Education (ACE) Grant$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/ace/$s$, $s$For public high school students on Georgia's Accelerated Career Diploma path who take a high-demand career program at a technical college. It covers tuition, waives fees and pays for required books.$s$, $s$Talk with your high school counselor about the Accelerated Career Diploma, then enroll in an eligible program at a TCSG college. Funding is requested through GAfutures, much like Dual Enrollment.$s$, $s$Standard tuition, mandatory fees waived, and required books, up to 15 semester hours per term$s$, null::int, $s$Offered every term; apply before the term starts$s$, $s$GA$s$, '{10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Trades$s$]::text[], null::text[], $s$technical$s$, null, $s$Must be a Georgia public high school student pursuing the Accelerated Career Diploma, in an associate of applied science, licensure diploma, or two related technical certificates on the High Demand Career List. Hours count toward the Dual Enrollment 30-hour cap.$s$, false),
  ($s$scholarship$s$, $s$DREAMS Scholarship$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/dreams/$s$, $s$Need-based aid for Pell Grant-eligible Georgia residents working on an associate or bachelor's degree at a University System of Georgia or technical college school. It helps fill the gap left after other grants.$s$, $s$File the FAFSA and enroll at an eligible USG or TCSG college; the college decides who receives it and may have its own application. Complete the online Financial Toolkit sessions in your GAfutures account before the first payment.$s$, $s$Up to $1,500 per term and $3,000 per year, limited to your unmet need$s$, 3000, $s$Set by each college; ask your financial aid office$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, null::text[], null::text[], $s$any$s$, null, $s$Must be Pell Grant eligible, enrolled in at least 6 hours in an associate or bachelor's program at a USG or TCSG school, and keep a 2.0 college GPA. After the first term, students must do at least 60 hours of paid or unpaid work (jobs, internships, volunteering) each term. Funds are limited, so colleges award first to those who qualify early.$s$, false),
  ($s$scholarship$s$, $s$Georgia Foster Care Scholarship$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/foster-care-scholarship/$s$, $s$Pays college costs such as tuition, fees, books and housing for Georgia students who spent time in foster care with DFCS or were adopted from DFCS custody after age 14.$s$, $s$Apply through GAfutures and your college's financial aid office before the term. Awards are first come, first served while funds last.$s$, $s$Your direct college costs (tuition, fees, books, room and board), up to $30,000 a year$s$, 30000, $s$Apply early; awards are first come, first served$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], array[$s$Foster care experience$s$]::text[], $s$any$s$, null, $s$Must be under 26 and a Georgia resident, enrolled in at least 6 hours at an eligible Georgia college. Must meet one pathway: in DFCS foster care for at least 6 months after turning 14, currently in DFCS custody or its independent living program, adopted from DFCS after 14, or in a family receiving state-funded adoption services.$s$, false),
  ($s$grant$s$, $s$Georgia Public Service Memorial Grant$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/public-service-memorial/$s$, $s$Helps pay college costs for the children and spouses of Georgia public safety officers (police, firefighters, EMTs, paramedics, prison guards and others) or public school employees who were killed or permanently disabled in the line of duty.$s$, $s$Fill out Part A of the application, have your college's financial aid office complete Part B, then upload it with documents about the incident through the GAfutures upload portal. You must reapply each year.$s$, $s$Cost of attendance minus other aid, up to $18,000 a year and $72,000 total$s$, 72000, $s$No fixed date; awards are first come, first served, so apply early each year$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], array[$s$Child of a first responder$s$]::text[], $s$any$s$, null, $s$Parent or spouse must have been a Georgia public safety officer permanently disabled or killed in the line of duty, or a public school employee killed or permanently disabled by an act of violence on the job. Must attend an eligible Georgia college.$s$, false),
  ($s$scholarship$s$, $s$Georgia HERO Scholarship$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/hero/$s$, $s$For Georgia National Guard members and U.S. Military Reservists who served in a combat zone, and for their children and spouses. Helps pay for college at Georgia public or private schools.$s$, $s$Fill out the HERO Scholarship form (linked from the GAfutures page) no later than two years after you become eligible, and renew each academic year.$s$, $s$Up to $2,000 a year, up to $8,000 total$s$, 8000, $s$Within two years of becoming eligible; renew every year$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent must have been a Georgia resident in the Georgia National Guard or U.S. Military Reserves deployed to a designated combat zone for at least 181 days (or evacuated for severe injury), with service starting on or after Feb. 1, 2003. Child must have been born before or within nine months of that service and been 25 or younger at the time. Must be a Georgia resident for 12 months before the term.$s$, false),
  ($s$grant$s$, $s$Inclusive Postsecondary Education (IPSE) Grant$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/ipse/$s$, $s$Helps students with intellectual disabilities pay tuition and program fees in an approved inclusive college program at schools such as UGA, Georgia Tech, Kennesaw State, Georgia State and others.$s$, $s$Get admitted to an approved IPSE program at a participating college, then apply through that college and GAfutures. The college confirms your enrollment.$s$, $s$Up to $13,000 a year at most four-year schools (amounts vary by college)$s$, 13000, $s$Set by each IPSE program; ask the college$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], array[$s$Student with a disability$s$]::text[], $s$any$s$, null, $s$Must have a qualifying intellectual disability, be a Georgia resident, and be enrolled in an approved IPSE program (e.g., Albany Tech, Berry, Columbus State, Georgia College, Georgia Tech, Georgia Southern, Georgia State, Kennesaw State, UGA).$s$, false),
  ($s$grant$s$, $s$University of North Georgia ROTC Grant$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/ung-rotc/$s$, $s$A yearly grant for Georgia residents attending the University of North Georgia full time and taking part in its ROTC program.$s$, $s$Enroll full time at UNG and join ROTC; apply through UNG and GAfutures each year.$s$, $s$Up to $1,500 a year ($750 per fall and spring term)$s$, 1500, $s$Each academic year; check with UNG$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], null::text[], $s$four_year$s$, $s$University of North Georgia$s$, $s$Must be a Georgia resident, full-time undergraduate at UNG, and enrolled in ROTC each term paid. Cannot receive this and the Future Officers grant in the same term.$s$, false),
  ($s$grant$s$, $s$University of North Georgia ROTC Grant for Future Officers$s$, $s$Georgia Student Finance Commission$s$, $s$https://gafutures.org/hope-state-aid-programs/scholarships-grants/ung-rotc/$s$, $s$A larger yearly grant for UNG ROTC students who commit to becoming Army officers.$s$, $s$Enroll full time at UNG in ROTC and apply through UNG and GAfutures; by the end of junior year you must sign a contract to accept an Army commission.$s$, $s$Up to $4,000 a year ($2,000 per fall and spring term)$s$, 4000, $s$Each academic year; check with UNG$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], null::text[], $s$four_year$s$, $s$University of North Georgia$s$, $s$Same as the UNG ROTC Grant, plus a contract to accept a commission as an Army officer by the end of junior year.$s$, false),
  ($s$scholarship$s$, $s$Georgia Military College State Service Scholarship$s$, $s$Georgia Student Finance Commission / Georgia Military College$s$, $s$https://gafutures.org/hope-state-aid-programs/military/gmc-state-service-program/$s$, $s$A two-year full-cost scholarship to Georgia Military College's Milledgeville campus for students who serve in the Georgia National Guard. It is technically a service-cancelable loan: you repay it with Guard service instead of money.$s$, $s$File the FAFSA, then complete the GMC State Service application with an essay, photo, school recommendation and a nomination from your Georgia state legislator. Your counselor sends your transcript, senior schedule and SAT/ACT scores to GMC Admissions.$s$, $s$Up to full cost of attendance (tuition, fees, room, meals, books, uniforms) minus other grants, for two years$s$, null::int, $s$Usually spring of senior year; confirm with GMC Admissions$s$, $s$GA$s$, '{12}'::int[], 2.5, null, 800, 17, null::int, false, true, array[$s$Government$s$]::text[], null::text[], $s$any$s$, $s$Georgia Military College$s$, $s$Must serve four years in the Georgia National Guard (two while at GMC, two after) or repay the money as a loan. Georgia resident for 12 months, nominated by a member of the Georgia General Assembly, meet Guard health standards, and enroll full time.$s$, false),
  ($s$scholarship$s$, $s$University of North Georgia Military Service Scholarship$s$, $s$Georgia Student Finance Commission / University of North Georgia$s$, $s$https://gafutures.org/hope-state-aid-programs/military/ung-military-program/$s$, $s$A full four-year scholarship to the University of North Georgia's Corps of Cadets for students who will become part-time Army officers in the Georgia Army National Guard. It is a service-cancelable loan repaid through Guard service.$s$, $s$Apply through UNG's online portal with an essay, school recommendation, transcript, SAT or ACT score, senior schedule, and a nomination form from a Georgia state legislator, and sign the promissory note.$s$, $s$Full four years of tuition, fees, room, meals, books and uniforms$s$, null::int, $s$Senior year; check UNG's application page for the date$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Leadership$s$,$s$Government$s$]::text[], null::text[], $s$four_year$s$, $s$University of North Georgia$s$, $s$Must enlist in the Georgia Army National Guard, join UNG's Corps of Cadets, and commission as a second lieutenant after graduating; otherwise the money must be repaid. Georgia resident for 12 months, nominated by a Georgia legislator, strong high school record, and meet Guard health standards.$s$, false),
  ($s$scholarship$s$, $s$Georgia Foundation Scholarship for Agriculture$s$, $s$Georgia Foundation for Agriculture (Georgia Farm Bureau)$s$, $s$https://www.gafoundationag.org/scholarships$s$, $s$For Georgia high school seniors who plan to study agriculture, environmental sciences, family and consumer sciences, forestry or a related field at a Georgia college with an agriculture program.$s$, $s$Apply online through the Georgia Foundation for Agriculture's scholarship page by March 1 of senior year.$s$, $s$Ten $3,000 awards; the top two applicants get an extra $1,500$s$, 4500, $s$March 1 of senior year$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$,$s$Agriculture$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must be a Georgia resident with high school leadership activities, majoring in an agriculture-related field at a USG school, Berry College, Emmanuel College, or another accredited Georgia college with an agriculture program. Must earn at least a 3.0 GPA in the first college semester; money is paid in the spring.$s$, false),
  ($s$scholarship$s$, $s$Georgia 4-H Foundation Scholarships$s$, $s$Georgia 4-H Foundation$s$, $s$https://georgia4hfoundation.org/scholarships/$s$, $s$A group of more than a dozen scholarships for Georgia 4-H members heading to college, including the Georgia 4-H Achievement Scholarship (for UGA's agriculture college), 4-H Dollars for 4-H Scholars, and need-based awards.$s$, $s$Apply through the Georgia 4-H Foundation scholarship application; the 2027 application opens December 1, 2026. Ask your county 4-H agent for help.$s$, $s$Varies by scholarship; Georgia 4-H awards over $50,000 a year in total$s$, null::int, $s$Application opens December 1; deadline usually in early spring$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Must be a Georgia 4-H member. Most awards are for incoming college freshmen no older than 19 on January 1 of the application year. Some require a financial need statement, an agriculture or forestry major, or attending UGA, ABAC, or a USG college.$s$, false),
  ($s$scholarship$s$, $s$Georgia's Ford Dealers Scholarship (Georgia FFA Foundation)$s$, $s$Georgia FFA Foundation$s$, $s$https://www.georgiaffa.org/page.aspx?ID=8030$s$, $s$For Georgia FFA members who are graduating seniors planning to earn a college degree related to agriculture. About twenty awards are given each year.$s$, $s$Complete the online Georgia Ford Dealers Scholarship application linked from the Georgia FFA post-secondary scholarships page in the spring of senior year.$s$, $s$$1,000 (about twenty awards)$s$, 1000, $s$Usually late March or early April of senior year$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a Georgia FFA member and incoming college freshman planning an agriculture-related degree. Georgia FFA also offers the Growing America's Farmers Scholarship (eight $1,000 awards) for students going into production agriculture.$s$, false),
  ($s$scholarship$s$, $s$Nancy Penn Lyons Scholarship$s$, $s$Community Foundation for Greater Atlanta$s$, $s$https://cfgreateratlanta.org/?p=1099$s$, $s$A renewable scholarship for strong Georgia high school seniors who are committed to community service.$s$, $s$Apply through the Community Foundation for Greater Atlanta's online scholarship portal (opens in December) with your FAFSA Submission Summary, transcript, SAT or ACT report and an essay.$s$, $s$Up to $6,000 a year for four years$s$, 24000, $s$Usually early March (2026 cycle ran Dec. 8 to March 2)$s$, $s$GA$s$, '{12}'::int[], 3.0, null, 1000, 22, null::int, true, false, array[$s$Community service$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a graduating Georgia high school senior with a commitment to community service. SAT score is reading plus math.$s$, false),
  ($s$scholarship$s$, $s$Community Foundation for Greater Atlanta General Scholarship$s$, $s$Community Foundation for Greater Atlanta$s$, $s$https://cfgreateratlanta.org/?p=1099$s$, $s$One universal application that considers students for many named scholarship funds at the Atlanta-area community foundation, judged on grades, work, community involvement and financial need.$s$, $s$Create an account on the foundation's scholarship portal and submit the universal application, essay (about 500 words), transcript, FAFSA Submission Summary and SAT/ACT report as PDFs.$s$, $s$Varies by fund$s$, null::int, $s$Usually early March (2026 cycle ran Dec. 8 to March 2); no extensions$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Must plan to enroll full time. Some funds are limited to students from certain towns or areas in metro Atlanta; read each fund's description in the portal.$s$, false),
  ($s$scholarship$s$, $s$Dream's Squared Scholarship$s$, $s$Community Foundation for Greater Atlanta$s$, $s$https://cfgreateratlanta.org/?p=1099$s$, $s$For students with financial need and a GPA between 2.0 and 3.0 who are headed to a two- or four-year college full time. A good option for students who miss the cutoff for most merit awards.$s$, $s$Apply through the Community Foundation for Greater Atlanta's online scholarship portal, which opens in December.$s$, $s$Varies$s$, null::int, $s$Usually early March (2026 cycle closed March 2)$s$, $s$GA$s$, '{12}'::int[], 2.0, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$GPA must be between 2.0 and 3.0. Must be accepted to an accredited two- or four-year school and enroll full time.$s$, false),
  ($s$scholarship$s$, $s$Mayor's Youth Scholarship$s$, $s$Community Foundation for Greater Atlanta / City of Atlanta$s$, $s$https://cfgreateratlanta.org/?p=1099$s$, $s$For Atlanta Public Schools graduates and City of Atlanta residents going to a two- or four-year college. There is no minimum GPA, and Pell Grant recipients get priority.$s$, $s$Apply through the Community Foundation for Greater Atlanta's online scholarship portal, which opens in December.$s$, $s$Varies$s$, null::int, $s$Usually early March (2026 cycle closed March 2)$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Must be an Atlanta Public Schools graduate, a City of Atlanta resident, or recommended by a City of Atlanta employee. Must not have received it before and must be accepted to a two- or four-year school.$s$, false),
  ($s$scholarship$s$, $s$Community Foundation of Central Georgia Scholarships$s$, $s$Community Foundation of Central Georgia (Macon)$s$, $s$https://cfcga.org/?p=92$s$, $s$One universal online application that matches Middle Georgia students to many local scholarship funds, some based on financial need.$s$, $s$Create an account on the foundation's online scholarship portal and complete the universal application with a transcript, a recommendation letter and a photo, plus any extra questions for scholarships you are matched to.$s$, $s$Varies by fund$s$, null::int, $s$Opens December 15 and closes February 28 at noon$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Most funds are for students from Macon and the surrounding Middle Georgia counties; each fund has its own rules.$s$, false),
  ($s$scholarship$s$, $s$North Georgia Community Foundation Scholarships$s$, $s$North Georgia Community Foundation$s$, $s$https://www.ngcf.org/scholarships$s$, $s$One application for more than 80 local scholarship funds for students in North Georgia (including Hall, Forsyth, Habersham and nearby counties). Recently it gave 327 awards totaling about $823,000.$s$, $s$Apply through the NGCF online scholarship portal during the winter application window.$s$, $s$Varies by fund$s$, null::int, $s$Usually mid-January to early March (2026 cycle ran Jan. 15 to March 2)$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Most funds are limited to students from certain North Georgia counties or high schools; check each fund's rules in the portal.$s$, false),
  ($s$scholarship$s$, $s$Community Foundation for the CSRA Scholarships$s$, $s$Community Foundation for the Central Savannah River Area (Augusta)$s$, $s$https://www.cfcsra.org/?p=3267$s$, $s$Local scholarships for graduating seniors in the Augusta area, including awards for STEM, skilled trades, agriculture and Eagle Scouts.$s$, $s$Create an account on the foundation's online scholarship portal and apply to the funds you qualify for; your counselor and references upload documents through emailed links.$s$, $s$About $500 to $2,000 depending on the fund$s$, null::int, $s$Most deadlines are around March 20 each year; some in May or July$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Must live in or graduate from a high school in Burke, Columbia, McDuffie, Richmond or Warren County, Georgia (or Aiken County, SC). Each fund has its own rules.$s$, false),
  ($s$scholarship$s$, $s$Walter Harrison Scholarship$s$, $s$Georgia EMC (through local electric membership cooperatives)$s$, $s$https://cobbemc.com/walter-harrison-scholarship$s$, $s$A $1,000 scholarship for students whose home gets power from a Georgia electric membership cooperative (EMC), for any accredited two- or four-year college or technical school in Georgia.$s$, $s$Get the application from your local EMC (for example Cobb, Jackson or Walton EMC) and submit it to them by their deadline; each EMC forwards finalists to a statewide committee.$s$, $s$$1,000$s$, 1000, $s$Usually early February (Cobb EMC's 2026 deadline was Feb. 6); dates vary by EMC$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Primary home must be served by a participating Georgia EMC. Must attend an accredited Georgia college, university or technical school. Selection looks at GPA, SAT scores, honors and financial need.$s$, false),
  ($s$scholarship$s$, $s$Georgia Press Educational Foundation Scholarship$s$, $s$Georgia Press Educational Foundation$s$, $s$https://gapress.org/scholarships-internships/$s$, $s$For Georgia students with financial need and an interest in newspaper journalism who will attend a Georgia college. Seniors in high school may apply.$s$, $s$Download the application from the Georgia Press Association website and email it to the foundation by February 1; a counselor, principal, professor or Georgia Press member should recommend you.$s$, $s$Varies; paid directly to your college for tuition$s$, null::int, $s$February 1 (the page lists Feb. 1, 2027 for the 2027-28 cycle)$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, array[$s$Writing$s$]::text[], null::text[], $s$any$s$, null, $s$A parent must have been a Georgia resident for two years, or the student for three years. Must attend a Georgia college or university and show prior interest in newspaper journalism. Reapply each year.$s$, false),
  ($s$scholarship$s$, $s$SPJ Georgia High School Scholarship$s$, $s$Society of Professional Journalists, Georgia Chapter$s$, $s$https://spjgeorgia.com/2026/02/01/high-school-seniors-apply-for-an-spj-scholarship$s$, $s$Three $500 awards for Georgia public high school seniors who plan to major in journalism and are interested in digital, broadcast or podcast storytelling.$s$, $s$Download the application guidelines from the SPJ Georgia website and follow the submission steps; the chapter posts the call for applications in winter.$s$, $s$$500 (three winners)$s$, 500, $s$Usually winter to spring of senior year; check the guidelines$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Writing$s$]::text[], null::text[], $s$any$s$, null, $s$Must attend a public high school in Georgia and plan to declare journalism as a college major.$s$, false),
  ($s$scholarship$s$, $s$GAE Foundation High School Senior Scholarship for Future Teachers$s$, $s$Georgia Association of Educators Foundation$s$, $s$https://gae.org/grants$s$, $s$For Georgia public high school seniors who plan to major in education at a Georgia college or university.$s$, $s$Download the fillable application from the GAE Foundation grants page; applications are posted each October.$s$, $s$Not stated$s$, null::int, $s$Applications open in October; check the form for the due date$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Education$s$]::text[], null::text[], $s$any$s$, null, $s$Must graduate this year from a Georgia public high school and attend a Georgia college or university as an education major.$s$, false),
  ($s$scholarship$s$, $s$Hispanic Alliance GA Scholarship$s$, $s$Hispanic Alliance GA (administered by Scholarship America)$s$, $s$https://scholarshipamerica.org/?p=30804$s$, $s$For Georgia high school seniors headed to a two- or four-year college or technical school full time, judged on grades, leadership, community involvement, work, goals and financial need.$s$, $s$Apply online through Scholarship America when the program opens, uploading a full transcript and SAT/ACT scores if they aren't on it. Winners are told in late January.$s$, $s$$1,500, renewable for one more year (up to 8 awards)$s$, 3000, $s$Usually fall to early winter of senior year (currently closed; 2026 details listed as tentative)$s$, $s$GA$s$, '{12}'::int[], 2.0, $s$unweighted$s$, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Must be a Georgia resident and enroll full time for the whole upcoming year. The page does not say applicants must be Hispanic.$s$, false),
  ($s$scholarship$s$, $s$John W. Youtsey Memorial Scholarship$s$, $s$Hemophilia of Georgia$s$, $s$https://www.hog.org/programs/page/scholarships$s$, $s$For Georgia residents who are Hemophilia of Georgia clients with hemophilia, von Willebrand disease or another inherited bleeding disorder and are going to college, technical school or a professional program.$s$, $s$Fill out the online pre-qualification form by mid-April; if you qualify, you'll get the full application by email.$s$, $s$Varies; the program has given more than 500 scholarships worth over $2 million$s$, null::int, $s$Pre-qualification due mid-April (April 15 in 2026)$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Student with a disability$s$]::text[], $s$any$s$, null, $s$Must have an inherited bleeding disorder, be a Hemophilia of Georgia client, and have lived in Georgia for at least one year. Recipients volunteer at least 12 hours with Hemophilia of Georgia.$s$, false),
  ($s$scholarship$s$, $s$Georgia Transplant Foundation Academic Scholarship$s$, $s$Georgia Transplant Foundation$s$, $s$https://gatransplant.org/our-programs/education-community-programs/academic-scholarships/$s$, $s$For Georgia students who are organ transplant recipients, living donors, or the children, parents or siblings of a transplant recipient, going to college or technical school.$s$, $s$Apply online or mail the paper application with transcripts, your acceptance letter, a personal statement of up to three pages and two recommendation letters, postmarked by May 1.$s$, $s$$1,000 a year, renewable for up to four years$s$, 4000, $s$Postmarked by May 1 each year$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Must be a Georgia resident and a transplant recipient, a dependent or parent of a recipient, a living donor, or a sibling of a recipient (sibling and recipient both 22 or younger).$s$, false),
  ($s$scholarship$s$, $s$GSGA Foundation Yates Scholarship$s$, $s$Georgia State Golf Association Foundation$s$, $s$https://gsga.org/foundation/scholarships$s$, $s$A renewable, need-based scholarship for students who work at a GSGA member golf club in Georgia (golf operations, course maintenance or clubhouse), or whose parent does. In 2026-27 the foundation gave about $447,000 to 80 scholars.$s$, $s$Apply online through the GSGA Foundation scholarship portal between September 1 and March 1; finalists are interviewed.$s$, $s$Varies; renewable through the fourth year of college$s$, null::int, $s$Application window September 1 to March 1 (open now for 2027-28)$s$, $s$GA$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Must be an employee of a GSGA member club, or the dependent of one. Georgia schools must be HOPE-eligible; out-of-state schools must be accredited. For a first bachelor's degree only.$s$, false),
  ($s$scholarship$s$, $s$Georgia ProStart Invitational Scholarships$s$, $s$Georgia Restaurant Association Foundation$s$, $s$https://www.garestaurants.org/gpsi$s$, $s$High school ProStart culinary and restaurant management teams compete statewide, and the top three teams in each contest win college scholarships. More than $150,000 was awarded in 2025.$s$, $s$Join your high school's ProStart program and compete in the Georgia ProStart Invitational, held each winter; your ProStart teacher registers the team.$s$, $s$Varies by placement$s$, null::int, $s$Competition held in late winter each year$s$, $s$GA$s$, '{10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Business$s$,$s$Trades$s$]::text[], null::text[], $s$any$s$, null, $s$Must be on a Georgia high school ProStart team and place in the top three in the Culinary or Management competition.$s$, false),
  ($s$scholarship$s$, $s$The Eichholz Law Firm Scholarship for High School Seniors$s$, $s$The Eichholz Law Firm$s$, $s$https://thejusticelawyer.com/scholarship$s$, $s$Four $1,000 awards for high school seniors in the Savannah area who are active in community service and extracurriculars.$s$, $s$Submit the online application with a 500-word original essay about your commitment to community service and activities; the application usually opens in spring.$s$, $s$$1,000 (four awards)$s$, 1000, $s$Usually late May (2026 deadline was May 29)$s$, $s$GA$s$, '{12}'::int[], 3.25, $s$unweighted$s$, null::int, null::int, null::int, false, false, array[$s$Community service$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a senior in Chatham, Effingham, Bryan or Liberty County, Georgia (or Allendale, Beaufort, Hampton or Jasper County, SC) and attend an accredited college in Georgia or South Carolina.$s$, false),
  ($s$scholarship$s$, $s$MTS Rising College Scholarship$s$, $s$Marine Technology Society$s$, $s$https://www.mtsociety.org/scholarships$s$, $s$A $2,500 scholarship for high school seniors who have been accepted into a marine studies program at a 2- or 4-year college. It is the only Marine Technology Society award open to high school seniors.$s$, $s$Join MTS as a student member, then apply online with an essay of up to 500 words, a list of marine activities and honors, a list of relevant courses, one recommendation letter and an unofficial transcript. The 2026 round has closed, and MTS says 2027 details will be posted in January.$s$, $s$$2,500 one-time$s$, 2500, $s$The 2026 round is closed. Details for 2027 are expected in January 2027.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Marine and ocean science$s$,$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$You must be an active MTS member (student membership is $25 a year) and be accepted into a 2- or 4-year marine studies program.$s$, false),
  ($s$scholarship$s$, $s$AMS First-Year Undergraduate Scholarship$s$, $s$American Meteorological Society$s$, $s$https://www.ametsoc.org/ams/information-for/students/ams-scholarships-and-fellowships/ams-freshman-undergraduate-scholarship/$s$, $s$A $5,000 scholarship, paid over the first two years of college, for high school seniors who plan to major in atmospheric, oceanic or hydrologic science. Ocean science majors qualify. Marine biology does not.$s$, $s$Apply online with the application form, an unofficial transcript covering the last three years of high school and one recommendation letter. The deadline is usually in early February of senior year.$s$, $s$$5,000 total ($2,500 a year for freshman and sophomore years)$s$, 5000, $s$Early February of senior year. The deadline for fall 2026 entry was February 6, 2026.$s$, $s$US$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, true, array[$s$Marine and ocean science$s$,$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$You must plan a degree in atmospheric science or a related ocean or water science. Marine biology does not count. You must enter college full-time in the fall after senior year. The second year's payment requires finishing freshman year successfully.$s$, false),
  ($s$scholarship$s$, $s$The Science Ambassador Scholarship$s$, $s$Cards Against Humanity$s$, $s$https://www.scienceambassadorscholarship.org/$s$, $s$Five $20,000 scholarships for women and non-binary students who will major in a STEM field. High school seniors and current undergraduates can apply.$s$, $s$Film a video of up to 3 minutes teaching a STEM topic you love, post it publicly on YouTube in widescreen format (not as a Short), and submit the online application by December 14, 2026.$s$, $s$$20,000 one-time, paid to your college$s$, 20000, $s$December 14, 2026, 11:59 PM Central Time$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], array[$s$Woman$s$]::text[], $s$any$s$, null, $s$Open to women and non-binary students. STEM must be your major for your whole undergraduate degree (a minor does not count). You must attend, or plan to attend, a college in the U.S. or a U.S. territory.$s$, false),
  ($s$scholarship$s$, $s$Brower Youth Awards$s$, $s$Earth Island Institute$s$, $s$https://www.broweryouthawards.org/programs/brower-youth-awards/apply/$s$, $s$An award for young people ages 13 to 22 who lead environmental projects in North America. Each winner gets $3,000, a short film about their work and a paid leadership trip.$s$, $s$Fill out the online application yourself and include a photo. Semifinalists are later asked for a support letter from someone who knows their environmental work (not a parent). The 2026 deadline was March 31.$s$, $s$$3,000 cash prize, plus a short film and a leadership trip$s$, 3000, $s$Usually late March. The 2026 deadline was March 31, 2026.$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$,$s$Leadership$s$]::text[], null::text[], $s$any$s$, null, $s$You must be 13 to 22 years old on the deadline, live in North America and lead environmental work. The prize is cash, not tied to college.$s$, false),
  ($s$scholarship$s$, $s$Dr. James Earl Kennamer Scholarship Program$s$, $s$National Wild Turkey Federation (NWTF)$s$, $s$https://your.nwtf.org/scholarships$s$, $s$Scholarships for graduating seniors who hunt and support wildlife conservation. Winners advance from local chapter to state to national, and the national winner receives $10,000.$s$, $s$Apply online through the NWTF scholarship portal to one local chapter by your state's deadline. You need a 400 to 600 word essay on conservation and hunting heritage, two recommendation letters from non-relatives and a copy of your hunting license.$s$, $s$Local and state awards vary; $10,000 for the national winner$s$, 10000, $s$The application opens November 1. Each state sets its own deadline, and the national winner is chosen by April 1, 2027.$s$, $s$US$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, false, array[$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$You must be an active hunter (send a copy of your hunting license) and a current NWTF member. You also need school and community leadership. You may apply to only one chapter.$s$, false),
  ($s$scholarship$s$, $s$Ducks Unlimited National Scholarship Program$s$, $s$Ducks Unlimited$s$, $s$https://www.ducks.org/get-involved/youth-programs/du-varsity/ducks-unlimited-national-scholarship-program$s$, $s$Scholarships for graduating seniors who are Ducks Unlimited members and care about wetlands and waterfowl conservation. Each year there are 61 awards, from $500 up to one $10,000 national scholarship.$s$, $s$Apply online by March 1, 2027. Include a transcript, your DU member and volunteer history, your awards, up to three recommendation letters and a 500-word essay on wetlands conservation.$s$, $s$50 awards of $500, 10 of $1,000 and 1 national award of $10,000, paid to your college$s$, 10000, $s$March 1, 2027 at midnight$s$, $s$US$s$, '{12}'::int[], 2.8, null, null::int, null::int, null::int, false, false, array[$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$You must be a Ducks Unlimited member. Students active in DU Varsity or local DU chapters get preference.$s$, false),
  ($s$scholarship$s$, $s$GACD Scholarship$s$, $s$Georgia Association of Conservation Districts$s$, $s$https://www.gacd.us/scholarships$s$, $s$A $1,000 scholarship for Georgia students with financial need who plan to study soil and water conservation or a related field. Examples include agronomy, horticulture and agricultural education.$s$, $s$Download the application from the GACD website and submit it with your transcript by December 31, 2026.$s$, $s$$1,000 (two payments of $500, one for each semester)$s$, 1000, $s$December 31, 2026$s$, $s$GA$s$, '{12}'::int[], 2.75, null, null::int, null::int, null::int, true, false, array[$s$Agriculture$s$,$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$You must be a Georgia resident and major, or plan to major, in a soil and water conservation-related field. Past winners cannot apply again.$s$, false),
  ($s$scholarship$s$, $s$GACD Auxiliary Scholarship$s$, $s$Georgia Association of Conservation Districts Auxiliary$s$, $s$https://www.gacd.us/scholarships$s$, $s$A $500 scholarship for Georgia students with financial need who plan to study a soil and water conservation-related field. The rules are the same as for the main GACD Scholarship.$s$, $s$Download the Auxiliary application from the GACD website and send it with a current transcript by December 31, 2026.$s$, $s$$500 one-time$s$, 500, $s$December 31, 2026$s$, $s$GA$s$, '{12}'::int[], 2.75, null, null::int, null::int, null::int, true, false, array[$s$Agriculture$s$,$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$You must be a Georgia resident and plan a soil and water conservation-related major. The money is paid after you finish one semester of full-time study.$s$, false),
  ($s$scholarship$s$, $s$Dr. Brian L. Davis Marine Biology, Conservation, and Education Scholarship$s$, $s$Georgia Aquarium$s$, $s$https://www.georgiaaquarium.org/remembering-brian/$s$, $s$A $20,000 scholarship ($5,000 a year for four years) for a public high school senior who will earn a bachelor's degree in marine biology, conservation, zoological sciences or science education.$s$, $s$Apply online by February 15, 2027. Include an essay of up to 1,000 words (in APA style) on the biggest threats to marine biodiversity and three science-based solutions, two recommendation letters, your transcript and a resume.$s$, $s$$20,000 total ($5,000 a year for four years)$s$, 20000, $s$February 15, 2027. The winner is announced April 15, 2027.$s$, $s$US$s$, '{12}'::int[], 2.5, null, null::int, null::int, null::int, false, false, array[$s$Marine and ocean science$s$,$s$Animals and veterinary$s$,$s$STEM$s$]::text[], null::text[], $s$four_year$s$, null, $s$You must attend a public high school in the U.S. and plan a bachelor's degree in one of the listed fields at a U.S. college. Starting at a 2-year college and then transferring is allowed. Children of Georgia Aquarium employees and volunteers cannot apply. You must keep a 2.5 GPA to renew.$s$, false),
  ($s$grant$s$, $s$Rising Explorer Grant$s$, $s$The Explorers Club$s$, $s$https://www.explorers.org/grants/rising-explorer-grant/$s$, $s$A research grant (about $2,000 on average) for high school and college students who plan their own field research project. Fields include biology, wildlife conservation, environmental science and marine and freshwater studies.$s$, $s$Fill out the online form with your project plan, timeline and budget, two letters of support and a short video. Applications for the 2027 field season have closed and will reopen in summer 2027.$s$, $s$Awards average about $2,000$s$, null::int, $s$Closed for the 2027 field season and reopening in summer 2027. The last deadline was August 31, 2026.$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$The money pays for a field research project that creates new knowledge. Trips, adventures and school field trips do not qualify. Open to students worldwide.$s$, false),
  ($s$scholarship$s$, $s$National Ocean Scholar Program$s$, $s$National Ocean Sciences Bowl (NOSB)$s$, $s$https://nosb.org/scholarship/$s$, $s$Up to $1,000 in college aid for graduating seniors who competed in the National Ocean Sciences Bowl at least once in high school and plan a career in ocean or environmental science.$s$, $s$Fill out the online application (a Google Form) in the spring of senior year. The 2026 round was due May 31, 2026.$s$, $s$Up to $1,000 for tuition, fees, books, a laptop or transportation$s$, 1000, $s$Late spring of senior year. The 2026 deadline was May 31, 2026.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Marine and ocean science$s$,$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$You must have competed on a National Ocean Sciences Bowl team during high school (Georgia has a regional NOSB competition). The money cannot pay for room and board.$s$, false),
  ($s$scholarship$s$, $s$The Earth Prize$s$, $s$Earth Foundation$s$, $s$https://www.theearthprize.org/2027$s$, $s$A worldwide environmental sustainability competition for students ages 13 to 19 with more than $100,000 in prizes. Seven regional winners each get $10,000 to carry out their idea.$s$, $s$Register on The Earth Prize website (registration runs until January 10, 2027) and submit your project by January 31, 2027.$s$, $s$$10,000 for each of seven regional winners, plus $500 mentor awards$s$, 10000, $s$Register by January 10, 2027. Projects are due January 31, 2027.$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Open to students ages 13 to 19 worldwide. The prize pays for putting a sustainability idea into action. It is not a tuition scholarship.$s$, false),
  ($s$scholarship$s$, $s$Non-Resident Merit Scholarships$s$, $s$College of Charleston$s$, $s$https://charleston.edu/cost-aid/scholarships/$s$, $s$Merit scholarships of $2,000 to $12,000 a year for out-of-state first-year students at the College of Charleston, which has a well-known marine biology program. Every non-resident applicant is considered.$s$, $s$Apply for admission. No separate scholarship application is needed.$s$, $s$$2,000 to $12,000 a year$s$, 12000, $s$Considered with your admission application. The page does not give a scholarship deadline.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$College of Charleston$s$, $s$For non-South Carolina residents entering as first-year students.$s$, true),
  ($s$scholarship$s$, $s$Out-of-State Freshman Merit Awards$s$, $s$Coastal Carolina University$s$, $s$https://coastal.edu/meritawards$s$, $s$Merit awards for out-of-state freshmen at Coastal Carolina, which has a large marine science program. Awards run from $4,500 a year up to $17,988 a year for the Presidential Scholarship.$s$, $s$Apply for admission by a priority deadline: October 15 (Early Decision), November 15 (Early Action) or February 1 (Regular Decision). You are considered automatically and told in your acceptance letter.$s$, $s$$4,500 to $17,988 a year, renewable for up to 4 years$s$, 71952, $s$Priority deadlines: October 15 (Early Decision), November 15 (Early Action), February 1 (Regular Decision). Money is limited after these dates.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Coastal Carolina University$s$, $s$There are no set GPA or test cutoffs; the whole application is reviewed. To renew, you need a 3.0 GPA and 30 credits each year.$s$, true),
  ($s$scholarship$s$, $s$Academic Achievement Scholarships$s$, $s$Eckerd College$s$, $s$https://www.eckerd.edu/admissions/?p=1244$s$, $s$Automatic tuition scholarships of $20,000 to $28,000 a year for first-year students at Eckerd College in St. Petersburg, Florida, a school known for marine science. The amount is based on your high school GPA.$s$, $s$Apply for admission for fall 2027. Students admitted without conditions are considered automatically.$s$, $s$$20,000 to $28,000 a year for up to 4 years$s$, 112000, $s$Considered with your admission application$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Eckerd College$s$, $s$Covers tuition only.$s$, true),
  ($s$scholarship$s$, $s$Community Engagement and Leadership Scholarship$s$, $s$Eckerd College$s$, $s$https://www.eckerd.edu/admissions/?p=1244$s$, $s$A $4,000-a-year scholarship plus a $2,000 study-abroad grant for incoming Eckerd College students with strong grades and a commitment to leadership and service.$s$, $s$Send the separate scholarship application by February 1, 2027.$s$, $s$$4,000 a year plus a $2,000 study-abroad grant$s$, null::int, $s$February 1, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Leadership$s$,$s$Community service$s$]::text[], null::text[], $s$four_year$s$, $s$Eckerd College$s$, null, false),
  ($s$scholarship$s$, $s$First-Year Research Associateships$s$, $s$Eckerd College$s$, $s$https://www.eckerd.edu/admissions/?p=1244$s$, $s$About 25 incoming Eckerd College students get a paid spot (up to $1,000) working on research with faculty in their first year. Many Eckerd students do research in marine science.$s$, $s$Send the separate application by February 1, 2027.$s$, $s$Stipend of up to $1,000 for one year$s$, 1000, $s$February 1, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Eckerd College$s$, $s$Students are chosen based on their whole high school record.$s$, false),
  ($s$scholarship$s$, $s$UTampa Presidential Merit Scholarship$s$, $s$The University of Tampa$s$, $s$https://www.ut.edu/admissions/financial-aid/ut-scholarships-and-grants$s$, $s$A merit scholarship of $10,000 to $18,000 a year for first-year students at the University of Tampa, which offers marine science and biology majors. Every high school applicant is considered.$s$, $s$Apply for admission. You are considered automatically, with emphasis on your unweighted GPA and how challenging your courses were.$s$, $s$$10,000 to $18,000 a year, renewable for up to 8 semesters$s$, 72000, $s$Decided at admission. Awards depend on available funds, so applying early helps.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Tampa$s$, $s$Leadership or community service is considered. You must stay full-time and keep making academic progress to renew. Award amounts cannot be appealed.$s$, true),
  ($s$scholarship$s$, $s$Florida Tech Merit Scholarship$s$, $s$Florida Institute of Technology$s$, $s$https://fit.edu/admission/scholarships--aid/university-scholarships-and-grants$s$, $s$A merit scholarship for first-time, full-time students, both in-state and out-of-state, at Florida Tech, which offers marine biology and ocean engineering. The award is based on weighted GPA and test scores.$s$, $s$Apply for admission. You are considered when you are admitted.$s$, $s$Amount varies (not listed); renewable for up to 9 semesters$s$, null::int, $s$Considered at admission$s$, $s$US$s$, '{12}'::int[], null::numeric, $s$weighted$s$, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Florida Institute of Technology$s$, null, true),
  ($s$grant$s$, $s$Florida Tech Scouting Grant (Eagle Scout and Gold Award)$s$, $s$Florida Institute of Technology$s$, $s$https://fit.edu/admission/scholarships--aid/university-scholarships-and-grants$s$, $s$$2,500 a year for incoming Florida Tech students who earned the Boy Scouts Eagle rank or the Girl Scouts Gold Award. It can be added on top of other Florida Tech scholarships.$s$, $s$Include a copy of your Eagle Scout or Gold Award certificate with your Florida Tech admission application.$s$, $s$$2,500 a year for up to 4 years$s$, 10000, $s$Submit with your admission application$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Florida Institute of Technology$s$, $s$You must have earned the Eagle Scout rank or the Girl Scout Gold Award and be a first-time, full-time student.$s$, false),
  ($s$scholarship$s$, $s$Academic Scholar Award for Nonresidents$s$, $s$University of South Carolina$s$, $s$https://sc.edu/about/offices_and_divisions/financial_aid/scholarships/scholarships_for_nonresidents/$s$, $s$Merit packages of $6,500 to $30,000 a year for out-of-state freshmen at the University of South Carolina, which has a marine science major. Students are considered automatically.$s$, $s$Apply for admission by December 1 to be considered. No separate scholarship application is needed.$s$, $s$$6,500 to $30,000 a year ($26,000 to $120,000 over four years)$s$, 120000, $s$Apply for admission by December 1$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of South Carolina$s$, $s$Only for first-time freshmen starting in the fall. Last year's recipients averaged scores like these: SAT 1300+, ACT 28+ and a high weighted GPA for the lowest tier. These are averages, not cutoffs. To renew, you need full-time enrollment and a 3.0 GPA.$s$, true),
  ($s$scholarship$s$, $s$Top Scholar Awards (Stamps, McNair and Horseshoe Scholars)$s$, $s$University of South Carolina$s$, $s$https://sc.edu/about/offices_and_divisions/financial_aid/scholarships/scholarships_for_nonresidents/$s$, $s$The University of South Carolina's top scholarships for out-of-state students, worth about $147,000 to $219,000 or more over four years. They include a cut to the in-state tuition rate, and Stamps and McNair add an enrichment fund.$s$, $s$Send the university application and the South Carolina Honors College application by November 15. Finalists interview and attend Top Scholar Weekend.$s$, $s$Horseshoe: $11,000 a year plus in-state tuition (over $147,000). McNair: $24,000 a year plus in-state tuition (over $199,000, plus a $14,000 enrichment fund). Stamps: about $219,000 plus a $15,000 enr$s$, 234000, $s$November 15 (Honors College application)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of South Carolina$s$, $s$You must apply to the South Carolina Honors College. An interview and Top Scholar Weekend are required.$s$, false),
  ($s$scholarship$s$, $s$Admissions Academic Merit Scholarship (Out-of-State)$s$, $s$University of West Florida$s$, $s$https://uwf.edu/admissions/undergraduate/cost-and-financial-aid/awards-and-scholarships/freshman-scholarships$s$, $s$Merit scholarships of $2,000 to $8,000 a year for out-of-state freshmen at the University of West Florida in Pensacola, which offers marine biology. The award is based on weighted GPA and test scores.$s$, $s$Complete your admission file, including test scores, by December 1, 2026 for summer or fall 2027 entry. Recipients are notified in December.$s$, $s$$8,000, $24,000 or $32,000 total ($2,000 to $8,000 a year over 4 years)$s$, 32000, $s$December 1, 2026 (complete admission file)$s$, $s$US$s$, '{12}'::int[], 3.7, $s$weighted$s$, 1160, 24, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of West Florida$s$, $s$Top tier: 4.0 weighted GPA and SAT 1400 or ACT 31. Some subject-area scores also count. Meeting the minimums does not guarantee an award. To renew, you need a 3.0 UWF GPA and 24 credits a year. No separate scholarship application is mentioned.$s$, false),
  ($s$scholarship$s$, $s$Out-of-State Freshman Admission Scholarship (Talent and Ability)$s$, $s$University of South Alabama$s$, $s$https://southalabama.edu/freshscholarships$s$, $s$Automatic scholarships for out-of-state freshmen at the University of South Alabama in Mobile, home to marine sciences and the Dauphin Island Sea Lab. Awards range from $2,500 a year to full tuition, and recipients also pay the in-state tuition rate.$s$, $s$Apply for admission by the February 15 priority deadline. Admitted freshmen are reviewed automatically and notified by email.$s$, $s$$2,500 a year up to full tuition, for 4 years, based on GPA and test scores, plus in-state tuition rate$s$, null::int, $s$February 15 priority admission and scholarship deadline$s$, $s$US$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of South Alabama$s$, $s$Open to U.S. citizens, permanent residents or qualified visa holders. Full tuition requires, for example, a 4.0 GPA with ACT 30 or SAT 1360, or a 3.5 GPA with ACT 32 or SAT 1420. You can send new scores in December, February or April for a possible increase.$s$, true),
  ($s$scholarship$s$, $s$Blue & Green Scholars Award and Director's Award$s$, $s$Florida Gulf Coast University$s$, $s$https://www.fgcu.edu/admissionsandaid/undergraduateadmissions/scholarshipsandwaivers$s$, $s$Merit awards of $10,000 or $15,000 a year for out-of-state freshmen at Florida Gulf Coast University, which offers marine science. Students who apply early are considered automatically.$s$, $s$Apply for admission by November 1 (Early Action is preferred). No separate scholarship application is needed.$s$, $s$Scholars Award: $15,000 a year. Director's Award: $10,000 a year. Up to 4 years.$s$, 60000, $s$Apply for admission by November 1 (the date for fall 2027 entry may have passed; check with FGCU)$s$, $s$US$s$, '{12}'::int[], 3.5, $s$weighted$s$, 1200, 25, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Florida Gulf Coast University$s$, $s$For non-Florida residents. The Scholars Award needs a 3.75 weighted GPA and SAT 1320 or ACT 28. The Director's Award needs a 3.5 weighted GPA and SAT 1200 or ACT 25. Awards are competitive and not guaranteed. To renew, you need a 3.0 GPA and 30 credits a year.$s$, true),
  ($s$scholarship$s$, $s$Out-of-State Tuition Waiver (Merit)$s$, $s$Florida State University$s$, $s$https://admissions.fsu.edu/first-year/scholarships$s$, $s$Covers all out-of-state tuition (about $73,808 over four years) for top non-Florida freshmen at Florida State, which offers marine biology and has a coastal marine lab. It is based on coursework and test scores.$s$, $s$Submit a complete admission application by the priority deadline to be considered automatically.$s$, $s$100% of out-of-state tuition, about $73,808 over 4 years$s$, 73808, $s$Complete your application by FSU's priority deadline (several FSU awards say to apply by December 1)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Florida State University$s$, $s$To renew, you need 15 credits a term and a 3.0 GPA. Some amounts on the page are labeled for students starting in fall 2024, so confirm current values.$s$, true),
  ($s$scholarship$s$, $s$President's Scholarship and Canes Achievement Award$s$, $s$University of Miami$s$, $s$https://admissions.miami.edu/undergraduate/financial-aid/scholarships/freshman$s$, $s$Merit scholarships for first-year students at the University of Miami, home of the Rosenstiel School of Marine, Atmospheric, and Earth Science. They are worth up to $30,000 a year (President's) or up to $20,000 a year (Canes Achievement).$s$, $s$Submit a complete admission application by your deadline. You are considered automatically, whatever admission plan you use.$s$, $s$Up to $30,000 a year (President's) or up to $20,000 a year (Canes Achievement), for up to 8 semesters$s$, 120000, $s$Considered with your admission application$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Miami$s$, $s$To keep it, you need full-time enrollment (24 credits a year) and a 3.0 GPA.$s$, true),
  ($s$scholarship$s$, $s$Premier Scholarships (Stamps, Isaac Bashevis Singer, Ronald A. Hammond, Weeks)$s$, $s$University of Miami$s$, $s$https://admissions.miami.edu/undergraduate/financial-aid/scholarships/freshman$s$, $s$The University of Miami's top first-year scholarships, covering full tuition or the full cost of attendance. Stamps also adds a $12,000 enrichment fund.$s$, $s$Apply Early Decision I or Early Action by November 1. Some Premier scholarships may ask for more information.$s$, $s$Full tuition (Singer, Hammond, Weeks) or full cost of attendance plus $12,000 (Stamps)$s$, null::int, $s$November 1 (Early Decision I or Early Action). For fall 2027 entry this date has passed.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Miami$s$, $s$The Hammond and Weeks scholarships are for U.S. citizens and permanent residents only.$s$, true),
  ($s$scholarship$s$, $s$George W. Jenkins Scholarship$s$, $s$University of Miami$s$, $s$https://admissions.miami.edu/undergraduate/financial-aid/scholarships/freshman$s$, $s$A full-cost-of-attendance scholarship plus a stipend at the University of Miami for students from eight Southeastern states, including Georgia. It looks at grades, financial need and overcoming hardship.$s$, $s$Your school counselor must nominate you. Apply Early Decision I or Early Action by November 1.$s$, $s$Full cost of attendance plus a stipend$s$, null::int, $s$November 1 (Early Decision I or Early Action). For fall 2027 entry this date has passed.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, null::text[], null::text[], $s$four_year$s$, $s$University of Miami$s$, $s$You must live in AL, FL, GA, KY, NC, SC, TN or VA and be nominated by your guidance counselor.$s$, false),
  ($s$scholarship$s$, $s$Non-Resident Academic Merit Scholarships (Presidential, Heritage, Charter)$s$, $s$Auburn University$s$, $s$https://auburn.edu/scholarship$s$, $s$Merit scholarships of $7,000 to $17,000 a year for out-of-state freshmen at Auburn, which offers fisheries and aquatic sciences, wildlife and a common pre-vet path. Awards are based on GPA and ACT or SAT score.$s$, $s$Get admitted by early February to be considered automatically. No scholarship application is needed. Send updated test scores by January 10.$s$, $s$$7,000 to $17,000 a year ($28,000 to $68,000 over 4 years)$s$, 68000, $s$Be admitted by early February. Updated test scores are due by January 10.$s$, $s$US$s$, '{12}'::int[], 3.5, null, null::int, 29, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$Auburn University$s$, $s$ACT 29-30 earns $7,000 a year, 31-32 earns $11,000, 33-34 earns $15,000 and 35-36 earns $17,000 (SAT equivalents accepted). The chart on the page is for fall 2026 entry, so amounts may change. To renew, you need a 3.0 Auburn GPA and 24 credits a year.$s$, true),
  ($s$scholarship$s$, $s$Coolidge Scholarship$s$, $s$Calvin Coolidge Presidential Foundation$s$, $s$https://coolidgescholars.org/$s$, $s$A full-ride, merit-based scholarship for high school juniors who show academic excellence, service, humility and an interest in public policy. It covers tuition, room, board and fees for four years at any accredited U.S. college.$s$, $s$Juniors apply online at coolidgescholars.org in the fall of junior year; all materials, including reference letters, are due by the December deadline.$s$, $s$Full tuition, room, board and required fees for four years, plus a yearly book stipend$s$, null::int, $s$December 1, 2026 at 5:00 PM Pacific (for juniors starting college in fall 2028)$s$, $s$US$s$, '{11}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], null::text[], $s$four_year$s$, null, $s$Must be a current high school junior who will start college full-time in fall 2028 (gap years and early graduation disqualify). Finalists interview in Vermont.$s$, false),
  ($s$scholarship$s$, $s$Profile in Courage Essay Contest$s$, $s$John F. Kennedy Library Foundation$s$, $s$https://www.jfklibrary.org/node/7165422$s$, $s$A national essay contest for high school students who write about an elected official who showed political courage. Winners earn cash awards for college.$s$, $s$Write a 700 to 1,000 word essay with at least five sources and submit it with the online registration form by the January deadline.$s$, $s$$10,000 first place; $3,000 second; $1,000 for each of three finalists$s$, 10000, $s$January 11, 2027 at 11:59 PM Eastern$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Writing$s$,$s$Government$s$]::text[], null::text[], $s$any$s$, null, $s$Open to U.S. students in grades 9-12 (public, private, home school) and U.S. citizens attending school overseas.$s$, false),
  ($s$scholarship$s$, $s$Voice of Democracy Scholarship Competition$s$, $s$Veterans of Foreign Wars (VFW)$s$, $s$https://www.vfw.org/VOD/$s$, $s$An audio-essay contest for high school students on a patriotic theme. Local, state and national winners earn scholarships, with a top national prize of $35,000.$s$, $s$Record a short audio essay on the year's theme and turn it in with the entry form to a participating local VFW Post by October 31.$s$, $s$Top national award $35,000; other national awards up to $21,000; state winners at least $1,000$s$, 35000, $s$October 31 each year (the 2026-27 deadline has passed; next one is October 31, 2027)$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Writing$s$,$s$Government$s$]::text[], null::text[], $s$any$s$, null, $s$Enter through a local VFW Post.$s$, false),
  ($s$scholarship$s$, $s$Patriot's Pen Youth Essay Contest$s$, $s$Veterans of Foreign Wars (VFW)$s$, $s$https://www.vfw.org/VOD/$s$, $s$A patriotic essay contest for middle school students (grades 6-8). Winners earn cash awards, with $5,000 for the national first-place winner.$s$, $s$Write a 300 to 400 word essay on the year's theme and turn it in with the entry form to a participating local VFW Post by October 31.$s$, $s$$5,000 national first place; state winners at least $500$s$, 5000, $s$October 31 each year (the 2026-27 deadline has passed)$s$, $s$US$s$, '{8}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Writing$s$,$s$Government$s$]::text[], null::text[], $s$any$s$, null, $s$Grades 6-8 only. Enter through a local VFW Post.$s$, false),
  ($s$scholarship$s$, $s$American Legion National High School Oratorical Contest$s$, $s$The American Legion$s$, $s$https://www.legion.org/get-involved/youth-programs/oratorical-contest/about-the-oratorical-contest$s$, $s$A speech contest about the U.S. Constitution for high school students. Winners advance from local to state to national rounds and earn college scholarships up to $25,000.$s$, $s$Contact your local American Legion post or the Georgia department to enter the post-level contest, usually held in winter; state winners go to the national finals in May.$s$, $s$$25,000 national winner; $22,500 second; $20,000 third; $2,000+ for each state winner at nationals$s$, 25000, $s$Local and state contests run in winter; state winners must be certified by April 5, 2027; national finals May 14-16, 2027$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Government$s$]::text[], null::text[], $s$any$s$, null, $s$Must be under 20 and in grades 9-12. Speak in the state where you live or attend school.$s$, false),
  ($s$scholarship$s$, $s$Army ROTC High School Scholarship$s$, $s$U.S. Army ROTC$s$, $s$https://www.goarmy.com/rotc/scholarships$s$, $s$A merit scholarship for students who want to become Army officers. It pays college tuition and fees (or room and board) plus monthly and book allowances, in exchange for military service after college.$s$, $s$Create an account and apply online starting in the summer before senior year; there are three review rounds, so applying early helps.$s$, $s$Full tuition and fees or room and board, $420 a month, and $1,200 a year for books$s$, null::int, $s$Round 1 Oct 12, 2026; Round 2 Jan 18, 2027; Round 3 Mar 8, 2027 (must start by Mar 4, 2027)$s$, $s$US$s$, '{12}'::int[], 2.5, $s$unweighted$s$, null::int, null::int, null::int, false, true, array[$s$Government$s$]::text[], null::text[], $s$any$s$, null, $s$Must take the SAT or ACT, pass an Army fitness test and meet body standards, and agree to serve as an Army officer (8-year obligation).$s$, false),
  ($s$scholarship$s$, $s$Navy ROTC National Scholarship$s$, $s$U.S. Navy (Naval Service Training Command)$s$, $s$https://www.netc.navy.mil/NSTC/NROTC/$s$, $s$A competitive merit scholarship for students who want to become Navy or Marine Corps officers. It pays tuition and fees plus a book stipend (or room and board) at participating colleges.$s$, $s$Apply online through the NROTC application website; the application period runs from April to December, and all documents go through your Navy ROTC coordinator.$s$, $s$Full tuition, educational fees, and a book stipend (or room and board)$s$, null::int, $s$Applications accepted April 1 to December 31; application website closes January 31$s$, $s$US$s$, '{12}'::int[], null::numeric, null, 1100, null::int, null::int, false, true, array[$s$Government$s$]::text[], null::text[], $s$four_year$s$, null, $s$ACT minimum is 22 English and 21 Math (44 combined); SAT minimum 1100 (540 Math, 550 reading). Must be 17 by Sept 1 of the college start year. Must serve as an officer after graduating.$s$, false),
  ($s$scholarship$s$, $s$Air Force ROTC High School Scholarship$s$, $s$U.S. Air Force ROTC$s$, $s$https://www.afrotc.com/scholarships/high-school/$s$, $s$A merit scholarship for students who want to become Air Force or Space Force officers. It pays college tuition plus a $900 yearly book stipend and a monthly allowance.$s$, $s$After junior year, create an account and apply online between July 1 and December 11; you'll upload transcripts, test scores and a fitness assessment.$s$, $s$Tuition (capped or uncapped), $900 a year for books, and $300-$500 a month$s$, null::int, $s$Application window July 1 to December 11, 2026 (for fall 2027 college entry)$s$, $s$US$s$, '{12}'::int[], 3.3, $s$unweighted$s$, 1310, 28, null::int, false, true, array[$s$Government$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must pass a fitness assessment and military medical exam, and serve at least four years on active duty after college.$s$, false),
  ($s$scholarship$s$, $s$Gloria Barron Prize for Young Heroes$s$, $s$Barron Prize$s$, $s$https://barronprize.org/$s$, $s$Honors young people ages 8 to 18 who have started and led a service project that helps people, animals or the planet. Each winner gets $10,000 for college or their project.$s$, $s$Complete a short pre-application online in winter, then a full application by mid-April.$s$, $s$$10,000 per winner$s$, 10000, $s$Pre-application usually January to March 15; full application due April 15 (2027 dates not posted yet)$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Community service$s$,$s$Leadership$s$]::text[], null::text[], $s$any$s$, null, $s$Ages 8-18 on April 15. Must be a U.S. or Canadian permanent legal resident with an SSN or tax ID. The project must be one you started and led, active within the past 12 months.$s$, false),
  ($s$scholarship$s$, $s$Breakthrough Junior Challenge$s$, $s$Breakthrough Prize Foundation$s$, $s$https://breakthroughjuniorchallenge.org/$s$, $s$A worldwide video contest for students ages 13 to 18 who explain a big idea in science or math. The winner receives a $250,000 college scholarship.$s$, $s$Make a short video explaining a science or math concept and submit it online during the summer window, then review other students' videos.$s$, $s$$250,000 college scholarship (plus prizes for the winner's teacher and school)$s$, 250000, $s$Entries usually open in May and close September 15 (2026 round closed; 2027 dates not posted yet)$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Ages 13-18. Entries must be in English.$s$, false),
  ($s$scholarship$s$, $s$Junior Science and Humanities Symposium (JSHS)$s$, $s$Department of Defense / Academy of Applied Science$s$, $s$https://jshs.org/$s$, $s$A research competition where high school students present original science, engineering or math research at regional and then national symposiums. Top presenters earn college scholarships.$s$, $s$Contact your regional JSHS (find it on jshs.org) and submit a research paper by the regional deadline, usually in winter.$s$, $s$Regional: $2,000 / $1,500 / $1,000; National: up to $12,000 per category winner (max $30,000 per student)$s$, 30000, $s$Regional symposiums are held in winter to early spring; check your region$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Must have done original research. National scholarship renewals require a 3.0 college GPA and a STEM major.$s$, false),
