  ($s$scholarship$s$, $s$Thermo Fisher Scientific Junior Innovators Challenge$s$, $s$Society for Science / Thermo Fisher Scientific$s$, $s$https://www.societyforscience.org/jic/$s$, $s$The top national science and engineering competition for middle school students (grades 6-8). Students nominated from local science fairs compete for awards, with a top prize of $25,000.$s$, $s$Compete at a Society-affiliated science fair; if nominated, complete the online application, usually due in early June.$s$, $s$Top award $25,000; over $100,000 in total awards$s$, 25000, $s$2026 application ran February 1 to June 10; 2027 dates not posted yet$s$, $s$US$s$, '{8}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Grades 6-8 in the U.S. Must be nominated by placing in the top 10% at an affiliated science fair.$s$, false),
  ($s$scholarship$s$, $s$3M Young Scientist Challenge$s$, $s$3M and Discovery Education$s$, $s$https://www.youngscientistlab.com/challenge$s$, $s$A video science contest for students in grades 5-8 who propose an invention that solves an everyday problem. The national winner receives $25,000 and a 3M mentorship.$s$, $s$Submit a short video explaining your idea at YoungScientistLab.com; entries usually open in January and close in late April.$s$, $s$$25,000 grand prize$s$, 25000, $s$2026 entries closed April 30, 2026; the 2027 contest usually opens in January$s$, $s$US$s$, '{8}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Grades 5-8 only.$s$, false),
  ($s$scholarship$s$, $s$U.S. Stockholm Junior Water Prize$s$, $s$Water Environment Federation$s$, $s$https://www.wef.org/membership--community/students--young-professionals/sjwp/about-the-stockholm-junior-water-prize$s$, $s$A competition for high school students who have done a water-related science research project. State winners go to nationals, where the U.S. winner gets a $10,000 scholarship and a trip to Stockholm.$s$, $s$Enter your water research paper online for your state competition (through a science fair or by self-nominating); state winners are named in early May.$s$, $s$$10,000 scholarship for the U.S. national winner$s$, 10000, $s$State competitions run in spring; national finals in June$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Must be at least 15 by August 1 of the competition year and have completed a water-related science project.$s$, false),
