  ($s$scholarship$s$, $s$George S. and Stella M. Knight Essay Contest$s$, $s$National Society Sons of the American Revolution (SAR)$s$, $s$https://sar.org/george-s-stella-m-knight-essay-contest/$s$, $s$An essay contest for high school students about the American Revolution, the Declaration of Independence or the Constitution. Winners move from chapter to state to national levels.$s$, $s$Write an 800 to 1,200 word essay and submit it through a local SAR chapter; in Georgia the deadline is December 1.$s$, $s$Cash awards at chapter, state and national levels$s$, null::int, $s$Georgia deadline December 1 (other states mostly December 31)$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Writing$s$,$s$Government$s$]::text[], null::text[], $s$any$s$, null, $s$U.S. citizens or legal residents. Contact your local SAR chapter's essay chair.$s$, false),
  ($s$scholarship$s$, $s$Stephen J. Brady Stop Hunger Scholarship$s$, $s$Sodexo Stop Hunger Foundation$s$, $s$https://us.stop-hunger.org/grants/youth-scholarships$s$, $s$For young people ages 5 to 25 who are fighting hunger in their communities. National winners get a $10,000 scholarship plus a $5,000 grant for their hunger charity.$s$, $s$Apply online during the annual window, which runs August 20 to October 20.$s$, $s$$10,000 scholarship plus $5,000 for a hunger-relief charity$s$, 10000, $s$Annually August 20 to October 20 (the 2026 window has closed)$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Community service$s$]::text[], null::text[], $s$any$s$, null, $s$Must be doing hands-on work to fight hunger.$s$, false),
  ($s$scholarship$s$, $s$Evans Scholarship$s$, $s$Western Golf Association / Evans Scholars Foundation$s$, $s$https://www.wgaesf.org/$s$, $s$A full housing and tuition scholarship for golf caddies with strong grades, financial need and good character. Scholars attend partner universities, mostly in the Midwest.$s$, $s$Apply online starting August 1 of senior year; school evaluations, transcript and caddie evaluation are due September 30, and the CSS Profile and FAFSA by October 15.$s$, $s$Full tuition and housing$s$, null::int, $s$Applications open August 1 of senior year; materials due September 30 (class of 2027 window has passed)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, array[$s$Sports$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must have caddied regularly for at least two years and be sponsored by a golf club. B+ or better in college-prep courses. Must attend an Evans partner university.$s$, false),
