  ($s$scholarship$s$, $s$American Welding Society Foundation Scholarships$s$, $s$American Welding Society Foundation$s$, $s$https://www.aws.org/career-resources/students/scholarships/$s$, $s$Millions in scholarships for students entering welding and related programs, from short certificates to two- and four-year degrees.$s$, $s$Fill out one online application at scholarship.aws.org; it shows every scholarship you qualify for.$s$, $s$$1,000 to $10,000+$s$, null::int, $s$National, district and section scholarships due March 1; Welder Training Scholarship due November 30, 2026$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Trades$s$]::text[], null::text[], $s$any$s$, null, $s$Must be enrolled or about to enroll in a welding program (at least 50% welding coursework). Some awards need AWS membership (free for students) or U.S. citizenship.$s$, false),
  ($s$scholarship$s$, $s$Young American Creative Patriotic Art Contest$s$, $s$VFW Auxiliary$s$, $s$https://vfwauxiliary.org/what-we-do/scholarships-2/$s$, $s$A patriotic art contest for high school students, with national prizes for two-dimensional art and a separate 3-D art category. You don't need a family link to the VFW.$s$, $s$Make your artwork and turn it in, with the entry form, to a local VFW Auxiliary that takes part in the contest (use the Auxiliary locator). Entries mailed straight to national headquarters are disqualified.$s$, $s$National 2-D prizes: $15,000 (1st), $7,500, $3,500, $1,500, $1,500, $1,000; 3-D prizes: $2,500 (1st) down to $500$s$, 15000, $s$Entries are due to the local VFW Auxiliary by March 31$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Arts$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a lawful permanent resident or have applied for permanent residency with plans to become a citizen (citizens qualify). Must be under 20. Foreign exchange students and past national winners can't enter.$s$, false),
  ($s$scholarship$s$, $s$Optimist International Oratorical Contest$s$, $s$Optimist International$s$, $s$https://www.optimist.org/member/scholarships4.cfm$s$, $s$A speech contest run by local Optimist Clubs in the US, Canada and the Caribbean, with scholarships at the district, regional and World Championship levels. The 2026-27 topic is "How My Actions Strengthen Those Around Me."$s$, $s$Write and practice a speech on the topic and enter through a local Optimist Club (email programs@optimist.org to find one). Club contests usually finish by late March; winners move up to district, regional and the World Championships in July 2027.$s$, $s$District: $2,500 / $1,500 / $1,000 (may vary); regional winners $5,000; World Championship $15,000 / $10,000 / $5,000$s$, 15000, $s$Set by each local club; club contests usually end by late March 2027$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Must be under 19 on October 1, 2026 and not yet finished high school. International program (US, Canada, Caribbean).$s$, false),
  ($s$scholarship$s$, $s$Zonta International Young Women in Leadership Award$s$, $s$Zonta International Foundation$s$, $s$https://www.zonta.org/Web/Programs/Education/Zonta_Young_Women_in_Leadership_Award.aspx$s$, $s$An international award for young women ages 16 to 19 who lead and volunteer in their communities. Winners move up from local Zonta clubs to district and then 37 international awards.$s$, $s$Find a nearby Zonta club with the Club Locator and get its deadline and the 2027 application; applications must be typed. If no club is near you, Zonta headquarters or an e-Club can help.$s$, $s$37 international awards of $5,000 each; club and district awards vary$s$, 5000, $s$Set by each local Zonta club (check with the club)$s$, $s$US$s$, '{10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Leadership$s$,$s$Community service$s$]::text[], array[$s$Woman$s$]::text[], $s$any$s$, null, $s$Must be 16 to 19 on April 1 and live in a Zonta district. International program; Zonta club members (other than Z club and Golden Z club members) can't apply.$s$, false),
