  ($s$grant$s$, $s$WDHOF Basic Dive Training Grants$s$, $s$Women Divers Hall of Fame (WDHOF)$s$, $s$https://www.wdhof.org/scholarship/basic-dive-training-grants$s$, $s$Grants that pay for learn-to-scuba (open water) certification, a helpful start for future marine biology students. Some grants are set aside for young women 15 to 21 and for people under 21 who can't afford training.$s$, $s$Fill out WDHOF's online eligibility form and application with two recommendation letters between October 1 and November 30, 2026. You may apply for only one WDHOF scholarship or grant.$s$, $s$$1,200 per grant for dive training (some of it can go to basic gear)$s$, 1200, $s$Due November 30, 2026, 5:00 pm New York time; awards announced mid-February 2027$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Marine and ocean science$s$]::text[], null::text[], $s$any$s$, null, $s$Training must lead to a certification from a recognized scuba agency. Funds must be used by August 31, 2028. Open to applicants worldwide.$s$, false),
  ($s$grant$s$, $s$J. Berman Memorial Grant for Sea Turtle Conservation$s$, $s$Women Divers Hall of Fame (WDHOF)$s$, $s$https://www.wdhof.org/scholarship/j-berman-memorial-grant-for-sea-turtle-conservation$s$, $s$A grant for a woman of any age to carry out a hands-on sea turtle conservation project. You don't need to be enrolled in a degree program.$s$, $s$Apply online through WDHOF between October 1 and November 30, 2026 with a clear conservation plan, a specific budget and two recommendation letters.$s$, $s$One $2,000 grant$s$, 2000, $s$Due November 30, 2026$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Marine and ocean science$s$]::text[], array[$s$Woman$s$]::text[], $s$any$s$, null, $s$Money must fund a sea turtle conservation activity (not research), and can't pay tuition or living costs. You may apply for only one WDHOF award.$s$, false),
  ($s$scholarship$s$, $s$MyImpact Challenge$s$, $s$Bill of Rights Institute$s$, $s$https://billofrightsinstitute.org/my-impact-challenge/$s$, $s$A national contest for middle and high school students who lead a service, volunteer or small-business project that tackles a problem in their community.$s$, $s$Lead your project, then submit a pitch video, impact summary, reflection essay and photos through the online portal between September 11, 2026 and April 19, 2027. Groups of up to five can enter together.$s$, $s$$10,000 grand prize, $5,000 second, $2,500 third, and up to nine $500 honorable mentions$s$, 10000, $s$Closes April 19, 2027, 11:59 pm Pacific$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Ages 13 to 19 and enrolled in middle or high school on January 1, 2027. Group entries split the prize.$s$, false),
  ($s$scholarship$s$, $s$JASNA Essay Contest (High School Division)$s$, $s$Jane Austen Society of North America (JASNA)$s$, $s$https://jasna.org/programs/essay-contest/$s$, $s$An essay contest about Jane Austen's novels, open to high school students anywhere in the world. You don't need to be a member.$s$, $s$The 2027 topic will be posted in November 2026 and submissions open in February 2027; enter on the JASNA website.$s$, $s$$1,000 first place (plus a trip to JASNA's annual meeting, travel not included), $500 second, $250 third$s$, 1000, $s$2027 deadline not yet posted; submissions open February 2027$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Writing$s$]::text[], null::text[], $s$any$s$, null, $s$International contest open to students worldwide, including homeschoolers.$s$, false),
  ($s$scholarship$s$, $s$Federal Junior Duck Stamp Contest$s$, $s$U.S. Fish and Wildlife Service$s$, $s$https://www.fws.gov/program/junior-duck-stamp/junior-duck-stamp-contest-information$s$, $s$A wildlife art contest for K-12 students: draw a North American duck, goose or swan. State winners go to the national contest, where the top artists win scholarships.$s$, $s$Make an original 9 x 12 inch hand-drawn piece, attach the entry form (and reference form for grades 7-12), and mail it to the Georgia state coordinator by the state deadline.$s$, $s$2026 national prizes: $1,000 (1st), $500 (2nd), $200 (3rd), $200 (conservation message)$s$, 1000, $s$Set by each state coordinator (check the Georgia coordinator's date); usually in spring$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Arts$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a U.S. citizen, resident alien or national. One entry per student. Don't send art to the national office.$s$, false),
  ($s$scholarship$s$, $s$National Security Language Initiative for Youth (NSLI-Y)$s$, $s$U.S. Department of State$s$, $s$https://www.nsliforyouth.org/$s$, $s$A merit-based U.S. government scholarship to study Arabic, Chinese, Korean or Russian abroad in summer or for a year, or online. Seniors who graduate between December 2026 and June 2027 can still apply.$s$, $s$Apply online at nsliforyouth.org by November 12, 2026 at 4:00 pm ET. No earlier language study is needed.$s$, $s$Scholarship for the study-abroad program (the page doesn't list a dollar value; passport costs not covered)$s$, null::int, $s$Due November 12, 2026, 4:00 pm ET$s$, $s$US$s$, '{9,10,11,12}'::int[], 2.5, null, null::int, null::int, null::int, false, true, null::text[], null::text[], $s$any$s$, null, $s$U.S. citizens only (permanent residents can't apply). Must be 15 to 18 at the program start (summer 2027 birthdates July 3, 2008 to June 10, 2012). International study-abroad program.$s$, false),
  ($s$scholarship$s$, $s$University of St Andrews International Excellence Scholarship$s$, $s$University of St Andrews (Scotland)$s$, $s$https://www.st-andrews.ac.uk/study/scholarships/scholarships-catalogue/undergraduate-scholarships/international-excellence-scholarship/$s$, $s$A full-tuition merit scholarship for an international (including US) student starting an undergraduate degree at St Andrews in Scotland in 2027. Biology is one of the eligible schools.$s$, $s$Apply to a St Andrews course, then use the international undergraduate scholarship form in My Application with a motivation statement and two references by January 27, 2027. You don't need an offer first.$s$, $s$Full tuition every year of the degree (one award)$s$, null::int, $s$Opened August 17, 2026; closes January 27, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of St Andrews$s$, $s$Study abroad in Scotland. Must have overseas fee status. Not for Medicine or the joint William & Mary degree. Winners join the Student Ambassadors Scheme.$s$, false),
  ($s$scholarship$s$, $s$UBC International Scholars Program$s$, $s$University of British Columbia (Canada)$s$, $s$https://you.ubc.ca/financial-planning/scholarships-awards-international-students/international-scholars/$s$, $s$UBC's top awards for international students entering from high school who have all A's and real financial need, including the Karen McKellin International Leader of Tomorrow Award. You're considered for every award you fit.$s$, $s$Apply to UBC, then submit the International Scholars application by November 15, 2026 (11:59 pm PT). Your school counselor or principal must nominate you and a teacher must give a reference.$s$, $s$Award values aren't listed; some awards go up to the full cost of the program and living expenses$s$, null::int, $s$Due November 15, 2026; documents by January 31, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$four_year$s$, $s$University of British Columbia$s$, $s$Study abroad in Canada. Must be an international student on a Canadian study permit, with all A's, and be nominated by your high school (each school can nominate up to two).$s$, false),
  ($s$scholarship$s$, $s$University of Glasgow World Changers Global Excellence Scholarship$s$, $s$University of Glasgow (Scotland)$s$, $s$https://www.gla.ac.uk/scholarships/worldchangersglobalexcellencescholarship/$s$, $s$An automatic merit discount on tuition for international students, including Americans, who get an offer to start a Glasgow undergraduate degree in 2027. The larger award covers Medical, Veterinary and Life Sciences and Science and Engineering.$s$, $s$No separate application: you're assessed when you get an offer and told within two weeks. Common App applicants can ask the admissions team through the enquiry form.$s$, $s$£10,000 a year (Medical, Veterinary & Life Sciences; Science & Engineering) or £7,000 a year (Arts; Social Sciences), renewable$s$, null::int, $s$No separate deadline; follows your admission offer$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Glasgow$s$, $s$Study abroad in Scotland. Needs international fee status and grades at the program's required level. Can't be combined with most other Glasgow awards.$s$, true),
  ($s$scholarship$s$, $s$Aberdeen Global Scholarship (Undergraduate)$s$, $s$University of Aberdeen (Scotland)$s$, $s$https://www.abdn.ac.uk/study/funding/645$s$, $s$An automatic tuition discount for new self-funded international undergraduates, including students from the US, starting at Aberdeen in 2026/27 or 2027/28.$s$, $s$No application needed; the award is applied automatically and shown on your CAS once you're admitted.$s$, $s$£6,000 off tuition every year of the degree$s$, null::int, $s$No deadline (available until further notice)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Aberdeen$s$, $s$Study abroad in Scotland. Must have international fee status and be self-funded, studying on the Aberdeen campus. Not for Medicine, Dentistry or DPLP.$s$, true),
  ($s$scholarship$s$, $s$Exeter Excellence Undergraduate Scholarship$s$, $s$University of Exeter (England)$s$, $s$https://www.exeter.ac.uk/study/funding/award/?id=5910$s$, $s$150 merit scholarships for international undergraduates starting at the University of Exeter in September 2027.$s$, $s$Get an offer for an eligible degree, then submit the scholarship web form with a 300-word statement by March 4, 2027 (Round 1). Results come by April 6, 2027.$s$, $s$£15,000 off international tuition each year$s$, null::int, $s$Round 1 closes March 4, 2027, 11:59 GMT$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$University of Exeter$s$, $s$Study abroad in England. Must have international fee status, be self-funded and hold an offer for an eligible campus-based bachelor's degree (not Medicine). Expected grades around AAB at A level or the equivalent.$s$, false),
  ($s$scholarship$s$, $s$McGill University Entrance Scholarships$s$, $s$McGill University (Canada)$s$, $s$https://www.mcgill.ca/studentaid/scholarships-aid/future-undergrads/entrance-scholarships$s$, $s$Merit scholarships for first-time undergraduates at McGill in Montreal. Every applicant who meets the grade bar is considered for a one-year award, and you can apply separately for larger renewable awards.$s$, $s$For the one-year award, just send all your grades with your admission application. For major awards, submit the separate scholarship application in the Applicant Portal soon after applying (opens October 1).$s$, $s$One-year award: $3,000 CAD; major renewable awards: $3,000 to $12,000 CAD a year (some limited to Canadians)$s$, null::int, $s$Apply soon after your admission application; see McGill's deadlines page$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$four_year$s$, $s$McGill University$s$, $s$Study abroad in Canada. The $12,000-a-year awards are only for Canadian citizens and permanent residents; the page doesn't say which other major awards US students can get.$s$, false),
  ($s$scholarship$s$, $s$Joseph S. Rumbaugh Historical Oration Contest$s$, $s$National Society Sons of the American Revolution (SAR)$s$, $s$https://www.sar.org/joseph-s-rumbaugh-historical-oration-contest/$s$, $s$A memorized 5-to-6-minute speech contest about a Revolutionary War event, person or document, for students in grades 9-12. Winners move from local SAR chapters to state and national rounds.$s$, $s$Find your local SAR chapter (or Georgia's state education chair), get its deadline and forms, and deliver your speech without notes. Chapter deadlines are usually two to four months before the national date.$s$, $s$National: $8,000 (1st), $5,000 (2nd), $3,000 (3rd), $500 for other finalists, $200 for other national contestants$s$, 8000, $s$Chapter deadlines vary (usually winter); state winners are due to national by May 15$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Speech must mention the nation's 250th anniversary and be delivered from memory with no props.$s$, false),
  ($s$scholarship$s$, $s$DAR Good Citizens Award and Scholarship$s$, $s$Daughters of the American Revolution (DAR)$s$, $s$https://www.dar.org/national-society/scholarships/dar-related$s$, $s$Each high school can honor one senior as its DAR Good Citizen for dependability, service, leadership and patriotism. The honoree can then write an essay to compete for scholarships at the chapter, state, division and national levels.$s$, $s$Teachers and classmates choose the school's honoree; if chosen, you can enter the scholarship round with a personal statement and essay. Ask your counselor or a local DAR chapter for dates.$s$, $s$Scholarships at chapter, state, division and national levels (amounts not listed on the current page; DAR reported $5,000 for each national winner in 2022)$s$, null::int, $s$Set by the local DAR chapter, usually in fall and winter of senior year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Leadership$s$,$s$Community service$s$]::text[], null::text[], $s$any$s$, null, $s$Your school selects you (one senior per school). U.S. citizenship not required.$s$, false),
  ($s$scholarship$s$, $s$Dr. Aura-Lee A. and James Hobbs Pittenger American History Scholarship$s$, $s$Daughters of the American Revolution (DAR)$s$, $s$https://www.dar.org/national-society/scholarships/history-etc$s$, $s$A renewable DAR scholarship for graduating seniors who will concentrate in American history and American government in college. You don't need to be connected to DAR.$s$, $s$Apply through the DAR online scholarship portal between November 1 and January 31 (11:59 pm Hawaii time), with proof of citizenship, transcript and recommendations.$s$, $s$$2,000 a year, renewable for up to four years$s$, 8000, $s$Applications accepted November 1 through January 31$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, array[$s$Government$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must take at least 24 credit hours in American history and government. Renewal needs a 3.25 GPA. U.S. citizens only; DAR sponsorship not required.$s$, false),
  ($s$scholarship$s$, $s$Arthur M. and Berdena King Eagle Scout Contest$s$, $s$National Society Sons of the American Revolution (SAR)$s$, $s$https://www.sar.org/arthur-m-berdena-king-eagle-scout-contest/$s$, $s$A national scholarship contest for Eagle Scouts who write a 500-word patriotic essay and complete a family tree chart.$s$, $s$Download the application, fill out a four-generation ancestor chart, write the essay and send it to your local SAR chapter by its deadline. State winners are due to national headquarters February 15.$s$, $s$National: $10,000 (1st), $6,000, $4,000, $2,000, $1,000, then $500 and $200 awards$s$, 10000, $s$Chapter deadlines vary; state winners due to national by February 15$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Must be an Eagle Scout registered in an active unit and not turn 19 during the contest year.$s$, false),
  ($s$scholarship$s$, $s$ASHG DNA Day Essay Contest$s$, $s$American Society of Human Genetics (ASHG)$s$, $s$https://www.ashg.org/dna-day/$s$, $s$An international genetics essay contest (750 words or fewer) for students in grades 9-12. Winning students get cash prizes and their teachers can get lab equipment grants.$s$, $s$A teacher (or a parent for homeschoolers) submits your essay on ASHG's submission site during the winter window. In 2026 the window ran January 9 to March 4.$s$, $s$2026 prizes: $1,000 (1st), $600 (2nd), $400 (3rd)$s$, 1000, $s$2027 dates not posted yet; in 2026 submissions ran January 9 to March 4$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], null::text[], $s$any$s$, null, $s$Open to students in the US and other countries; essays in English, one author each.$s$, false),
  ($s$scholarship$s$, $s$WTS Transportation YOU High School Scholarship$s$, $s$WTS Foundation (WTS International)$s$, $s$https://www.wtsinternational.org/wts-foundation/scholarships$s$, $s$A scholarship for girls in high school who are studying science, technology, engineering and math and are interested in transportation careers.$s$, $s$Apply through a local WTS chapter (Georgia has a chapter), which sets its own deadline. Chapters submit their winners to the WTS Foundation between December 14, 2026 and January 15, 2027.$s$, $s$$2,500$s$, 2500, $s$Set by your local WTS chapter; chapter nominations are due January 15, 2027$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], array[$s$Woman$s$]::text[], $s$any$s$, null, $s$Local chapters may add their own requirements.$s$, false),
  ($s$scholarship$s$, $s$AISES Indigenous Peoples Education Fund Scholarship$s$, $s$American Indian Science and Engineering Society (AISES)$s$, $s$https://aises.org/scholarships/$s$, $s$A STEM scholarship from AISES for first-year college students who are enrolled members of a state or federally recognized tribe.$s$, $s$Join AISES (free for students) and apply in the AISES portal between December 15 and April 30; recommendation letters are due May 7.$s$, $s$$5,000$s$, 5000, $s$Applications open December 15 and close April 30$s$, $s$US$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, false, array[$s$STEM$s$]::text[], array[$s$American Indian or Alaska Native$s$]::text[], $s$any$s$, null, $s$Must be a full-time first-year student in a STEM field at an accredited college and a current AISES member.$s$, false),
  ($s$scholarship$s$, $s$AFA Scholarships$s$, $s$Agriculture Future of America (AFA)$s$, $s$https://www.agfuture.org/scholarships$s$, $s$Scholarships for graduating seniors and college students in agriculture or food-related degrees who plan careers in food, agriculture or natural resources. Every award includes a spot at the AFA Leaders Conference.$s$, $s$Apply online through AFA's portal by March 4, 2027; fill in work, activities and service sections fully. Winners are named in early June.$s$, $s$$1,600 to $3,200, plus AFA Leaders Conference admission (travel not included)$s$, 3200, $s$Due March 4, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, array[$s$Agriculture$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must be 17 to 25 at the time of the conference and plan a four-year degree. A 2.5 GPA or higher is recommended.$s$, false),
