  ($s$scholarship$s$, $s$FRA Americanism Essay Contest$s$, $s$Fleet Reserve Association (FRA)$s$, $s$https://www.fra.org/fra/Web/Web/Content/Essay_Contest.aspx$s$, $s$A 350-word patriotic essay contest for students in grades 7-12. Local winners move to regional and national judging.$s$, $s$Pick the FRA branch nearest you from the list on the contest page and send your essay and cover sheet to that branch by December 1, 2026.$s$, $s$National: $1,500 grand prize; other national winners $1,000, $750, $500$s$, 1500, $s$Due December 1, 2026 (2026-27 contest)$s$, $s$US$s$, '{8,9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Writing$s$]::text[], null::text[], $s$any$s$, null, $s$Must enter through an FRA member or local branch; homeschoolers welcome.$s$, false),
  ($s$scholarship$s$, $s$Jean Ibendahl Scholarship (Daughters of American Agriculture)$s$, $s$American Agri-Women Foundation$s$, $s$https://www.americanagriwomen.org/scholarships$s$, $s$A scholarship for women ages 18-23 from farm, ranch or agribusiness families (or who work in agriculture themselves) taking courses directly related to agriculture.$s$, $s$Mail the application starting January 1; it must be postmarked by March 1.$s$, $s$$1,000$s$, 1000, $s$Applications accepted from January 1; postmarked by March 1$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Agriculture$s$]::text[], array[$s$Woman$s$]::text[], $s$any$s$, null, $s$Must be 18 to 23 and a farm, ranch or agribusiness woman or her daughter. AAW membership not required.$s$, false),
  ($s$scholarship$s$, $s$AKC Humane Fund John D. Spurling OBE Scholarship$s$, $s$AKC Humane Fund (American Kennel Club)$s$, $s$https://akchumanefund.org/john-d-spurling-scholarship-application/$s$, $s$Tuition help for full-time students in programs that teach responsible pet ownership and dog well-being, such as veterinary medicine, vet tech, animal care, animal behavior, grooming or training.$s$, $s$Fill out the application (it accepts high school transcripts and a school you plan to attend) and send it by the summer postmark deadline (July 1 in 2026).$s$, $s$Five scholarships a year totaling $10,000, paid to the school$s$, null::int, $s$Postmark deadline was July 1, 2026; expect a similar summer date in 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Animals and veterinary$s$]::text[], null::text[], $s$any$s$, null, $s$Must be a full-time student at an accredited U.S. school in a degree or certificate program whose curriculum includes responsible pet ownership.$s$, false),
  ($s$scholarship$s$, $s$NESA Eagle Scout Scholarships$s$, $s$National Eagle Scout Association (NESA)$s$, $s$https://nesa.org/scholarships/$s$, $s$Merit and need scholarships for Eagle Scouts from senior year of high school on, including the four-year Lawrence S. and Mabel Cooke Scholarship.$s$, $s$Apply in the NESA portal between December 1, 2026 and February 1, 2027 (11:59 pm CST). Your Eagle board of review must be on or before January 24, 2027.$s$, $s$Cooke Scholarship up to $50,000 over four years; other awards $4,000 to $30,000$s$, 50000, $s$Due February 1, 2027; winners announced June 10, 2027$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Must be an Eagle Scout and active NESA member, enrolled full time in an accredited degree or skilled trade program. Not for military academy students.$s$, false),
  ($s$scholarship$s$, $s$PHBA Youth Scholarship$s$, $s$Palomino Horse Breeders of America (PHBA) Youth Scholarship and Educational Fund$s$, $s$https://www.palominohba.com/the-association/youth-scholarships/scholarship-checklist/$s$, $s$A scholarship for high school seniors who have been Palomino Horse Breeders youth members and plan to go to college or a technical school full time.$s$, $s$Send the PHBA scholarship form with your transcript, test scores or class rank, two signed recommendation letters, a photo and a personal letter. Check PHBA's site for the 2027 deadline.$s$, $s$Amount not listed (plus a $250 award when you finish a bachelor's degree)$s$, null::int, $s$Was February 16 in 2025; 2027 date not posted$s$, $s$US$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, false, array[$s$Horses and equestrian$s$]::text[], null::text[], $s$any$s$, null, $s$Must have been a PHBA youth member in good standing for the past two years; one letter must come from a PHBA national director or youth advisor.$s$, false),
  ($s$scholarship$s$, $s$Robertson Scholars Leadership Program$s$, $s$Robertson Foundation$s$, $s$https://robertsonscholars.org/high-school-students-2/$s$, $s$A full-ride leadership scholarship at Duke and UNC-Chapel Hill, open to students from any state. It covers eight semesters plus funded summers and study abroad.$s$, $s$Submit the Robertson high school application by November 15, 2026 and apply separately to Duke and/or UNC-Chapel Hill by their deadlines.$s$, $s$Full tuition, room and board, and most mandatory fees for eight semesters, plus up to three funded summers$s$, null::int, $s$Regular deadline November 15, 2026 (early deadline was October 15)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Leadership$s$]::text[], null::text[], $s$four_year$s$, $s$Duke University or UNC-Chapel Hill$s$, $s$Must apply to Duke and/or UNC in the same year by their Early or Regular deadlines. Report SAT/ACT scores if you took them.$s$, false),
  ($s$scholarship$s$, $s$Jefferson Scholarship$s$, $s$Jefferson Scholars Foundation$s$, $s$https://www.jeffersonscholars.org/scholarships/selection$s$, $s$A full four-year scholarship to the University of Virginia for seniors with outstanding leadership, scholarship and citizenship. Students can't apply directly; schools in eligible regions nominate one senior.$s$, $s$Tell your school counselor you're interested; the counselor nominates through the Foundation's portal and materials are due December 1. Check whether your school's region can nominate.$s$, $s$Full financial support for four years at UVA, plus enrichment such as study abroad$s$, null::int, $s$School nominations and nominee materials due December 1$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Leadership$s$]::text[], null::text[], $s$four_year$s$, $s$University of Virginia$s$, $s$Nominated by your high school (one per school), and only if your school is in an eligible nominating region. Financial need and citizenship aren't considered.$s$, false),
  ($s$scholarship$s$, $s$Point Foundation Flagship Scholarship$s$, $s$Point Foundation$s$, $s$https://pointfoundation.org/scholarships/flagship$s$, $s$A scholarship with mentoring for LGBTQ+ students and allies, open to high school seniors heading to an accredited nonprofit U.S. college.$s$, $s$Apply online during the fall window, which closes November 19 at 5:00 pm PT for funding that starts in fall 2027.$s$, $s$Up to $15,000, for up to four years$s$, 15000, $s$Window opened September 9; closes November 19, 5:00 pm PT$s$, $s$US$s$, '{12}'::int[], 3.3, null, null::int, null::int, null::int, false, false, null::text[], null::text[], $s$any$s$, null, $s$Must be LGBTQ+ or an ally and enroll full time at an accredited nonprofit U.S. college (not a fully online program).$s$, false),
  ($s$scholarship$s$, $s$TMCF Enterprise Access HBCU Scholarship$s$, $s$Thurgood Marshall College Fund (TMCF) and Enterprise$s$, $s$https://tmcf.org/open-scholarships/2027-2028-tmcf-enterprise-access-hbcu-scholarship/$s$, $s$Need-based scholarships for full-time students in any major, including incoming freshmen, at a TMCF member HBCU in 2027-28.$s$, $s$Make a two-minute video on how you'll use your education to change the world and apply through the TMCF portal by January 8, 2027. File the FAFSA.$s$, $s$Up to $15,000 (81 scholars), paid in fall 2027 and spring 2028$s$, 15000, $s$Due January 8, 2027, 11:59 pm EST$s$, $s$US$s$, '{12}'::int[], 2.75, null, null::int, null::int, null::int, true, true, null::text[], null::text[], $s$four_year$s$, null, $s$Must enroll full time at a TMCF member HBCU (Georgia has several) and have a 2027-28 FAFSA on file.$s$, false),
  ($s$scholarship$s$, $s$TMCF McDonald's Black and Positively Golden Scholarship$s$, $s$Thurgood Marshall College Fund (TMCF) and McDonald's$s$, $s$https://tmcf.org/open-scholarships/2027-2028-tmcf-mcdonalds-black-and-positively-golden-scholarship/$s$, $s$Need-based scholarships for full-time HBCU undergraduates, including freshmen starting in 2027-28, who show leadership.$s$, $s$Apply through the TMCF scholarship portal with a 200-word essay by April 23, 2027.$s$, $s$Up to $15,000 (60 scholars), paid in fall 2027 and spring 2028$s$, 15000, $s$Due April 23, 2027, 11:59 pm EST$s$, $s$US$s$, '{12}'::int[], 2.7, null, null::int, null::int, null::int, true, true, array[$s$Leadership$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must enroll full time at an HBCU in 2027-28.$s$, false),
  ($s$grant$s$, $s$Federal Pell Grant$s$, $s$U.S. Department of Education$s$, $s$https://studentaid.gov/understand-aid/types/grants/pell$s$, $s$The main federal grant for undergraduates with financial need. It does not have to be paid back.$s$, $s$Fill out the FAFSA. There is no separate application, and your college lists your Pell amount in your financial aid offer.$s$, $s$Up to $7,395 a year for 2026-27 (minimum $740), based on financial need$s$, 7395, $s$File the FAFSA early in senior year. State and college aid deadlines come well before the federal one.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, null::text[], null::text[], $s$any$s$, null, $s$Must file the FAFSA. For 2026-27, students whose Student Aid Index (SAI) is $14,790 or higher (twice the maximum Pell) cannot get a Pell Grant. The cutoff does not apply to children of service members or public safety officers who died in the line of duty. Congress could change the maximum award.$s$, true),
  ($s$grant$s$, $s$Federal Supplemental Educational Opportunity Grant (FSEOG)$s$, $s$U.S. Department of Education (through participating colleges)$s$, $s$https://studentaid.gov/understand-aid/types/grants/fseog$s$, $s$An extra federal grant that colleges give to undergraduates with the greatest financial need, usually Pell Grant students.$s$, $s$Fill out the FAFSA early. Colleges that take part award FSEOG from limited funds, with no separate application.$s$, $s$$100 to $4,000 a year, set by the college$s$, 4000, $s$No separate deadline, but funds run out, so file the FAFSA as early as possible.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, null::text[], null::text[], $s$any$s$, null, $s$Only at colleges that take part. Colleges must give first priority to Pell Grant recipients with the lowest SAI. Not for students who already have a bachelor's degree.$s$, true),
  ($s$grant$s$, $s$TEACH Grant (Teacher Education Assistance for College and Higher Education Grant)$s$, $s$U.S. Department of Education$s$, $s$https://studentaid.gov/understand-aid/types/grants/teach$s$, $s$A federal grant for students training to be teachers who agree to teach for four years in a high-need subject at a low-income school. If the teaching service isn't completed, the grant turns into a loan that must be repaid with interest.$s$, $s$Fill out the FAFSA, enroll in a TEACH-eligible teaching program at a participating college, and sign the TEACH Grant Agreement to Serve or Repay. Ask the college's financial aid office for its TEACH request form.$s$, $s$Up to $3,772 a year for 2026-27 (cut from $4,000 by the federal budget sequester); $16,000 lifetime limit for undergraduates$s$, 16000, $s$Request it from your college before the term starts. Each college sets its own process.$s$, $s$US$s$, '{12}'::int[], 3.25, null, null::int, null::int, null::int, false, true, array[$s$Education$s$]::text[], null::text[], $s$any$s$, null, $s$Entering freshmen qualify with a 3.25 GPA or a score above the 75th percentile on at least one section of the SAT or ACT. Only at participating colleges, in a TEACH-eligible program. After graduating, you must teach full time for at least 4 years in a high-need field at a low-income school, or repay the grant as a loan with interest.$s$, false),
  ($s$grant$s$, $s$Maximum Pell Grant for children of fallen service members and public safety officers$s$, $s$U.S. Department of Education$s$, $s$https://studentaid.gov/understand-aid/types/grants/iraq-afghanistan-service$s$, $s$Students whose parent or guardian died in the line of duty in the U.S. military after 9/11, or as a police officer, firefighter, or other public safety officer, get the maximum Pell Grant no matter what their family income is. Since 2024-25 this replaces the old Iraq and Afghanistan Service Grant and the Children of Fallen Heroes Scholarship.$s$, $s$On the FAFSA, answer yes to the question about a parent killed in the line of duty, then send your college the documents it asks for.$s$, $s$The maximum Pell Grant, $7,395 for 2026-27$s$, 7395, $s$No separate deadline. File the FAFSA early in senior year.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, true, null::text[], array[$s$Military family$s$,$s$Child of a first responder$s$]::text[], $s$any$s$, null, $s$Parent or guardian died in the line of duty while on active duty in the U.S. Armed Forces on or after Sept. 11, 2001, or while serving as a public safety officer (police, firefighter, ambulance crew, and similar roles). Must be under 33 as of Jan. 1 before the award year. Lifetime limit of 12 semesters of Pell.$s$, true),
  ($s$grant$s$, $s$Workforce Pell Grant$s$, $s$U.S. Department of Education$s$, $s$https://www.ed.gov/about/news/press-release/us-department-of-education-issues-final-rule-create-new-workforce-pell-grant-program$s$, $s$A new kind of Pell Grant, starting July 1, 2026, that pays for short job-training programs (8 to 15 weeks) in high-demand fields that the state has approved.$s$, $s$Fill out the FAFSA and enroll in a program the college confirms is approved for Workforce Pell. Ask the college's financial aid office whether its program qualifies.$s$, $s$Pell Grant money for an approved short-term program; the amount depends on the program$s$, null::int, $s$No separate deadline. File the FAFSA before the program starts.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, array[$s$Trades$s$]::text[], null::text[], $s$technical$s$, null, $s$The program must last 8 to under 15 weeks (150 to 599 clock hours) and be approved by the state's governor and the U.S. Department of Education. Approvals began in August 2026 and are still rolling out, so Georgia programs may be limited at first. Federal loans, work-study and FSEOG are not available for these programs.$s$, true),
  ($s$grant$s$, $s$Survivors' and Dependents' Educational Assistance (DEA, Chapter 35)$s$, $s$U.S. Department of Veterans Affairs$s$, $s$https://www.va.gov/family-and-caregiver-benefits/education-and-careers/dependents-education-assistance/$s$, $s$Monthly VA education payments for children of veterans who have a permanent and total service-connected disability or who died from a service-connected cause or in the line of duty.$s$, $s$Apply online at VA.gov or mail VA Form 22-5490, then tell your college's VA certifying official that you applied.$s$, $s$$1,621 a month for full-time school (Oct. 2026 to Sept. 2027 rate), for up to 36 months$s$, null::int, $s$Apply any time once you are enrolled or about to enroll. Apply in spring of senior year so benefits are ready for fall.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent must be a veteran or service member with a permanent and total service-connected disability, or who died from a service-connected cause or in the line of duty. The program must be VA-approved. You can't use DEA and the Fry Scholarship at the same time. If you get Dependency and Indemnity Compensation (DIC), you must give it up while using DEA.$s$, false),
  ($s$scholarship$s$, $s$Marine Gunnery Sergeant John David Fry Scholarship (Fry Scholarship)$s$, $s$U.S. Department of Veterans Affairs$s$, $s$https://www.va.gov/family-and-caregiver-benefits/education-and-careers/fry-scholarship/$s$, $s$Post-9/11 GI Bill benefits for children of service members who died in the line of duty on or after Sept. 11, 2001. It pays tuition and fees, housing, and books.$s$, $s$Apply online at VA.gov or mail VA Form 22-5490, then ask your college's VA certifying official to submit your enrollment.$s$, $s$Tuition and fees, a monthly housing payment, and money for books and supplies, for up to 36 months$s$, null::int, $s$Apply any time after age 18 or high school graduation. Apply in spring of senior year so benefits are ready for fall.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent was a service member or Selected Reserve member who died in the line of duty on or after Sept. 11, 2001, or died of a service-connected disability (active duty members within 120 days of discharge). Must be 18 or a high school graduate. The school and program must be VA-approved. If you get DIC, you must give it up when you start using Fry.$s$, false),
  ($s$scholarship$s$, $s$Scholarships for Military Children$s$, $s$Fisher House Foundation and Defense Commissary Agency$s$, $s$https://corp.commissaries.com/Scholarship$s$, $s$500 scholarships of $2,000 a year for children of active duty, Guard and Reserve, retired, or deceased military members. At least one is awarded at each commissary location.$s$, $s$Create an account on the Fisher House scholarship site (militaryscholar.org), finish every section, write a 500-word essay, upload a transcript, and enter the benefits number from your military ID card.$s$, $s$$2,000$s$, 2000, $s$Usually mid-February of senior year (Feb. 11 for the 2026-27 cycle)$s$, $s$US$s$, '{12}'::int[], 3.0, $s$unweighted$s$, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Must be unmarried, under 23, and have a valid Uniformed Services ID card. Must enroll full time in a bachelor's program, or at a community college that lets you transfer directly to a four-year school. Students with a full scholarship or a service academy appointment are not eligible. The student must complete the application personally.$s$, false),
  ($s$scholarship$s$, $s$Fisher House Heroes' Legacy Scholarship$s$, $s$Fisher House Foundation$s$, $s$https://www.fisherhouse.org/programs/scholarship-programs/$s$, $s$College scholarships for children of service members who died or were seriously injured in the line of duty since Sept. 11, 2001.$s$, $s$Apply online through the Fisher House scholarship site. See the Heroes' Legacy FAQ on fisherhouse.org for this year's dates. You can also apply for Scholarships for Military Children.$s$, $s$Amount not listed on the official page$s$, null::int, $s$Check the Heroes' Legacy FAQ for the current deadline$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent died or was seriously injured in the line of duty on or after Sept. 11, 2001.$s$, false),
  ($s$scholarship$s$, $s$Folds of Honor Higher Education Scholarship$s$, $s$Folds of Honor Foundation$s$, $s$https://foldsofhonor.org/scholarships/$s$, $s$Need-based college scholarships for children and spouses of U.S. service members who died or were disabled, and of first responders who died or were catastrophically injured. Covers college, trade, and technical school.$s$, $s$Apply online at fohscholarships.communityforce.com during the yearly window (Feb. 1 to March 31). Each student needs a separate application.$s$, $s$Up to $2,500 per term ($1,250 for part-time), based on unmet need$s$, null::int, $s$Applications open Feb. 1 and close March 31 each year. Offers are emailed by the end of July.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Military family$s$,$s$Child of a first responder$s$]::text[], $s$any$s$, null, $s$Parent or spouse is a U.S. service member who died or was disabled, or a first responder who died or was catastrophically injured. The school must be accredited or state-registered. To keep the award, students need at least a 2.0 GPA each fall and spring term.$s$, false),
  ($s$scholarship$s$, $s$Children of Fallen Patriots Foundation College Scholarship (now Tunnel to Towers Mae and George Siller Scholarship Program)$s$, $s$Tunnel to Towers Foundation (formerly Children of Fallen Patriots Foundation)$s$, $s$https://t2t.org/mae-and-george-siller-scholarship-program/$s$, $s$Pays the gap between other benefits and the full cost of college for children of military members who died in the line of duty. Covers tuition, fees, books, housing, and living costs, and helps high schoolers with test and application costs.$s$, $s$Fill out the Family Enrollment Form and the Scholarship Enrollment Form, and a scholarship administrator will help with documents. Applications are reviewed year-round.$s$, $s$Covers remaining college costs (tuition, fees, books, housing, stipends) after other aid; amount depends on budget and is not guaranteed$s$, null::int, $s$Rolling; no single deadline$s$, $s$US$s$, '{11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Child of a military member who died in a line-of-duty-related incident, or of a family served by Tunnel to Towers' line-of-duty programs. Must be 33 or younger and keep at least a 2.0 semester GPA. You must use VA benefits and federal and state grants first. Children of Fallen Patriots joined Tunnel to Towers in 2026, and families should keep applying through CFP until a new process is announced.$s$, false),
  ($s$scholarship$s$, $s$The American Legion Legacy Scholarship$s$, $s$The American Legion$s$, $s$https://www.legion.org/get-involved/scholarships/the-american-legion-legacy-scholarship$s$, $s$Need-based scholarship for children of post-9/11 service members who died on active duty or have a VA disability rating of 50% or more.$s$, $s$Apply online at register.legion.org. Include the military death certificate or VA rating letter, your FAFSA Submission Summary, your college aid offer, and a list of costs.$s$, $s$Up to $20,000 for children of fallen service members; up to $5,000 for children of disabled veterans; you can reapply each year$s$, 20000, $s$March 24, 2027 for the 2027-28 school year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent served after Sept. 11, 2001 and either died on active duty (including federally activated Guard and Reserve) or was injured on active duty and has a combined VA disability rating of 50% or higher. Must be accepted to an accredited U.S. college. Covers the gap left after other aid and veterans' benefits.$s$, false),
  ($s$scholarship$s$, $s$MG James Ursano Scholarship Program for Dependent Children$s$, $s$Army Emergency Relief$s$, $s$https://www.armyemergencyrelief.org/scholarships/child/$s$, $s$Need-based scholarship for children of Army soldiers who are on active duty, retired, or deceased, toward a first bachelor's degree.$s$, $s$Read the yearly Program Guidelines, which link to the online application, and file the FAFSA. Reapply each year, for up to four years.$s$, $s$Varies each year based on your Student Aid Index, the budget, and college costs$s$, null::int, $s$Application window usually runs Jan. 1 to April 1 (April 1, 2026 for 2026-27)$s$, $s$US$s$, '{12}'::int[], 2.0, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Military family$s$]::text[], $s$four_year$s$, null, $s$Dependent of a soldier on federal active duty, retired, or who died on active or retired status. Children of Guard or Reserve soldiers qualify only if the soldier is on Title 10 orders for the whole school year. Must be under 24 and enrolled full time. FAFSA required.$s$, false),
  ($s$grant$s$, $s$General Henry H. Arnold Education Grant$s$, $s$Air Force Aid Society$s$, $s$https://afas.org/haparnoldgrant/$s$, $s$Need-based grant for children of Air Force and Space Force members who are on active duty, retired, or deceased.$s$, $s$File the FAFSA and apply online when the 2027-28 application opens in early January 2027.$s$, $s$Varies based on your Student Aid Index, cost of attendance, and the budget$s$, null::int, $s$2027-28 application opens early January 2027; see the AFAS timeline for the deadline$s$, $s$US$s$, '{12}'::int[], 2.0, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent is an Air Force or Space Force member on active duty (or Guard or Reserve on qualifying full-time orders), retired, or deceased while on active duty or retired. Must not turn 24 during the award year, must be a dependent student for FAFSA purposes, and must enroll full time at a school approved for federal aid.$s$, false),
  ($s$scholarship$s$, $s$Marine Corps Scholarship Foundation Undergraduate Scholarship$s$, $s$Marine Corps Scholarship Foundation$s$, $s$https://www.mcsf.org/apply/$s$, $s$Need-based scholarships for children of Marines and of Navy Corpsmen, Chaplains, and Religious Programs specialists who served with Marine units.$s$, $s$Apply online at mcsf.scholarshipapps.org between Jan. 1 and March 1. A separate Career & Technical Education scholarship takes applications year-round.$s$, $s$$2,500, $5,000, $7,500 or $10,000 a year, for up to four years$s$, null::int, $s$Applications open Jan. 1 and close March 1 each year$s$, $s$US$s$, '{12}'::int[], 2.0, null, null::int, null::int, 134000, true, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Child of an active-duty, reserve, or veteran Marine, or a Marine killed in service, or of a Navy Corpsman, Chaplain, or Religious Programs specialist attached to a Marine unit. For 2027-28 the family income limit is $134,000 adjusted gross income (tax year 2025). Families above it are considered only in extreme financial hardship. The school must be listed on College Navigator.$s$, false),
  ($s$grant$s$, $s$NMCRS Education Assistance Program$s$, $s$Navy-Marine Corps Relief Society$s$, $s$https://www.nmcrs.org/press-release/navy-marine-corps-relief-society-opens-applications-2026-2027-education-assistance$s$, $s$Need-based grants and interest-free loans for children of active-duty, retired, or deceased Navy and Marine Corps members.$s$, $s$Apply online at nmcrs.scholarshipapps.org during the spring application window.$s$, $s$Grants of $500 to $3,000; interest-free loans also available$s$, 3000, $s$Spring window (Feb. 16 to April 17 for 2026-27)$s$, $s$US$s$, '{12}'::int[], 2.0, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Dependent child under 23 (as of Sept. 30 of the award year) of an active-duty, retired, or deceased Navy or Marine Corps member. Full-time or part-time study at an accredited two-year, four-year, technical, or vocational school.$s$, false),
  ($s$scholarship$s$, $s$Coast Guard Foundation Scholarships for Coast Guard Children$s$, $s$Coast Guard Foundation$s$, $s$https://www.coastguardfoundation.org/education/coast-guard-children$s$, $s$College scholarships for children of active-duty, retired, and reserve Coast Guard members. Children of members who died in the line of duty can get Fallen Heroes Scholarships that cover all college and living costs.$s$, $s$Apply through the Foundation's online scholarship portal during the yearly scholarship season.$s$, $s$Varies; Fallen Heroes Scholarships cover 100% of college and living expenses$s$, null::int, $s$Yearly season (Feb. 1 to April 1 in 2026)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Parent is an active-duty, retired, or active reserve Coast Guard member, or died in operational, line-of-duty service.$s$, false),
  ($s$scholarship$s$, $s$Special Operations Warrior Foundation College Scholarship$s$, $s$Special Operations Warrior Foundation$s$, $s$https://specialops.org/sfo-educational-programs-2026/$s$, $s$College funding for surviving children of fallen Special Operations personnel and for children of Medal of Honor recipients. Covers tuition, books, fees, housing, meals, and more.$s$, $s$Email Scholarships@specialops.org or review the eligibility guidelines on the site. The foundation also reaches out to eligible families itself.$s$, $s$Tuition, books, fees, housing and meals, transportation, plus a laptop; up to $5,000 for college visits, application fees, and SAT/ACT prep$s$, null::int, $s$No set deadline listed; contact the foundation in high school$s$, $s$US$s$, '{9,10,11,12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Surviving child of fallen Special Operations personnel (or of a deceased non-serving spouse of Special Operations personnel), or child of any Medal of Honor recipient.$s$, false),
  ($s$scholarship$s$, $s$AMVETS Scholarship for Children and Grandchildren of Veterans$s$, $s$AMVETS$s$, $s$https://amvets.org/scholarships/$s$, $s$Yearly scholarships for children and grandchildren of U.S. veterans and current active-duty, Guard, and Reserve members. They help cover what is left after federal and state aid.$s$, $s$Apply through the AMVETS scholarship page. Check the page for this year's application dates.$s$, $s$$4,000$s$, 4000, $s$Not listed on the official page; check AMVETS for current dates$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Military family$s$]::text[], $s$any$s$, null, $s$Child or grandchild of a U.S. veteran or active-duty member (military, National Guard, or Reserves). Meant to fill the gap left after all federal and state grants and scholarships.$s$, false),
  ($s$scholarship$s$, $s$Jackie Robinson Foundation Scholarship$s$, $s$Jackie Robinson Foundation$s$, $s$https://jackierobinson.org/apply/$s$, $s$A scholarship with mentoring for high school seniors with financial need who show strong academics, leadership, and community service, and plan to attend a four-year college.$s$, $s$Apply online at connect.jackierobinson.org/apply with a transcript, ACT or SAT score, one recommendation, three short essays, and the CSS Profile.$s$, $s$Amount not listed on the official page$s$, null::int, $s$Jan. 14, 2027 at 5 p.m. ET (opened Sept. 1, 2026)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, array[$s$Leadership$s$,$s$Community service$s$]::text[], null::text[], $s$four_year$s$, null, $s$Must be a U.S. citizen and plan to attend a JRF-approved, accredited four-year college. CSS Profile required. The current eligibility list does not limit the award to students of color.$s$, false),
  ($s$scholarship$s$, $s$Hagan Scholarship$s$, $s$Hagan Scholarship Foundation$s$, $s$https://haganscholarships.org/application/$s$, $s$A scholarship for high-achieving seniors from families earning $125,000 or less who will attend a four-year college. Students must work a paid job during senior year.$s$, $s$Apply online by Dec. 1 of senior year with a transcript and an unsealed letter of recommendation.$s$, $s$Amount not listed on the application page; up to 1,500 scholarships for the class of 2027$s$, null::int, $s$Dec. 1, 2026 for the class of 2027$s$, $s$US$s$, '{12}'::int[], 3.5, null, null::int, null::int, 125000, true, false, null::text[], null::text[], $s$four_year$s$, null, $s$Must attend a U.S. public, private, charter, magnet, or STEM high school, and enroll at an eligible four-year college the fall after graduation (no community, junior, or online colleges). Must work 240 hours at a paid, supervised job outside the family between Jan. 1 and Sept. 1, 2027. Must apply for federal and state grants. Parents' 2025 adjusted gross income must be $125,000 or less.$s$, false),
  ($s$scholarship$s$, $s$TheDream.US National Scholarship$s$, $s$TheDream.US$s$, $s$https://www.thedream.us/scholarships/national-scholarship/$s$, $s$A large scholarship for undocumented, DACA, or TPS students with financial need who can't get federal aid, for study at one of TheDream.US Partner Colleges.$s$, $s$Check the Application Guide, then apply online between Nov. 1, 2026 and Feb. 28, 2027 using program key code "Dream."$s$, $s$Up to $36,000 for a bachelor's degree (up to $18,000 for an associate degree), plus up to $6,000 for books and supplies$s$, 36000, $s$Feb. 28, 2027 (opens Nov. 1, 2026)$s$, $s$US$s$, '{12}'::int[], 2.5, null, null::int, null::int, null::int, true, false, null::text[], array[$s$DACA or undocumented student$s$]::text[], $s$any$s$, null, $s$For first-generation immigrant students (undocumented, DACA, TPS, or pending application) who came to the U.S. before Nov. 1, 2021 and before age 16, and who are not eligible for federal aid. Must attend a Partner College in your state full time and qualify for in-state tuition at a public Partner College, or attend a private or online Partner College. Georgia families should check the Partner College list, because options in Georgia may be limited. TheDream.US's separate Opportunity Scholarship is not open to Georgia residents.$s$, false),
  ($s$scholarship$s$, $s$APIA Scholarship$s$, $s$APIA Scholars (Asian & Pacific Islander American Scholarship Fund)$s$, $s$https://apiascholars.org/scholarship/$s$, $s$Need-based college scholarships focused on students at or below the poverty line and first-generation college students. Historically for Asian American and Pacific Islander students, it now welcomes students of all backgrounds.$s$, $s$Apply online between Nov. 15, 2026 and Jan. 15, 2027. Sign up on the site for application updates.$s$, $s$$2,500 one-year awards up to $20,000 multi-year awards$s$, 20000, $s$Jan. 15, 2027 at 5 p.m. ET (opens Nov. 15, 2026)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, true, null::text[], null::text[], $s$any$s$, null, $s$Must be a U.S. citizen, national, or permanent resident (citizens of the Marshall Islands, Micronesia, and Palau also qualify). Must enroll in an associate or bachelor's program at an accredited U.S. college. Priority goes to students with very high financial need and first-generation college students.$s$, false),
  ($s$scholarship$s$, $s$McDonald's HACER National Scholarship$s$, $s$McDonald's USA and RMHC$s$, $s$https://www.mcdonalds.com/us/en-us/community/hacer/$s$, $s$College scholarships for high school seniors chosen for their grades, community impact, personal statement, and financial need. The program has historically served Hispanic students, but the current eligibility page does not list a heritage requirement.$s$, $s$Apply online by Feb. 15, 2027 with a transcript, a personal statement, and a list of community service. Semifinalists must send their FAFSA Submission Summary.$s$, $s$Amount not listed on the official page$s$, null::int, $s$Feb. 15, 2027$s$, $s$US$s$, '{12}'::int[], 2.8, null, null::int, null::int, null::int, true, false, null::text[], null::text[], $s$any$s$, null, $s$Must be under 21 and a legal U.S. resident, U.S. citizen, or DREAMer/DACA recipient. Must enroll full time at an accredited two- or four-year college or vocational/technical school the year after selection.$s$, false),
  ($s$scholarship$s$, $s$American Indian College Fund Full Circle Scholarship$s$, $s$American Indian College Fund$s$, $s$https://collegefund.org/students/scholarships/college-students/$s$, $s$Scholarships for American Indian and Alaska Native students at tribal colleges or other accredited nonprofit colleges. High school seniors can apply.$s$, $s$Submit one online application, which covers all College Fund scholarships you qualify for. Applications open Feb. 1, and applying by the May 31 priority deadline gives you the best chance.$s$, $s$Varies; awards average $2,000 to $3,000$s$, null::int, $s$Opens Feb. 1; priority deadline May 31 each year$s$, $s$US$s$, '{12}'::int[], 2.0, null, null::int, null::int, null::int, false, false, null::text[], array[$s$American Indian or Alaska Native$s$]::text[], $s$any$s$, null, $s$Must be an enrolled member of a state or federally recognized tribe or Alaska Native village, or a descendant through an enrolled parent or grandparent (with birth certificates). Must enroll full time at an accredited nonprofit college; for-profit schools are not eligible. Reapply each year.$s$, false),
  ($s$scholarship$s$, $s$Cobell Scholarship$s$, $s$Cobell Scholarship (administered by Indigenous Education, Inc.)$s$, $s$https://cobellscholar.org/how-to-apply/$s$, $s$Scholarships for enrolled members of federally recognized American Indian tribes and Alaska Native Corporations who study full time at a nonprofit college, community college, or trade school.$s$, $s$Create a profile in the OASIS online portal, fill out the eligibility form, and apply for the scholarships it matches you to. The undergraduate application opens Dec. 15 and is due March 31.$s$, $s$Amount not listed on the official page$s$, null::int, $s$Undergraduate: opens Dec. 15, due March 31 at 11:59 p.m. MT. Separate vocational and trade window.$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$American Indian or Alaska Native$s$]::text[], $s$any$s$, null, $s$Must be an enrolled member of a U.S. federally recognized tribe or Alaska Native Corporation and enroll full time in a degree or credential program at an accredited nonprofit school. The page does not say outright that high school seniors can apply, so confirm with scholarships@cobellscholar.org.$s$, false),
  ($s$scholarship$s$, $s$P.E.O. STAR Scholarship$s$, $s$P.E.O. Sisterhood$s$, $s$https://www.peointernational.org/resource/star-scholarship-procedures/$s$, $s$A competitive one-time scholarship for young women in their last year of high school, based on leadership, academics, activities, and community service.$s$, $s$A local P.E.O. chapter must recommend you and complete its part first. Then you finish the online application.$s$, $s$$2,500 one time$s$, 2500, $s$Set in the yearly STAR procedures; contact a local P.E.O. chapter early in senior year$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, array[$s$Leadership$s$,$s$Community service$s$]::text[], array[$s$Woman$s$]::text[], $s$any$s$, null, $s$Must be recommended by a local P.E.O. chapter. Must start full-time or part-time college in the U.S. or Canada the fall after graduation.$s$, false),
  ($s$scholarship$s$, $s$Anne Ford Scholarship$s$, $s$National Center for Learning Disabilities (NCLD)$s$, $s$https://www.ncld.org/what-we-do/scholarships/anne-ford-scholarship/$s$, $s$A four-year scholarship for high school seniors with a documented learning disability who will attend a four-year college full time. Students with ADHD who also have a learning disability are encouraged to apply.$s$, $s$Apply online through NCLD's Kaleidoscope link. Include your FAFSA information, one recommendation, three short answers (text, video, or audio), and proof of your learning disability (such as an IEP) as a PDF.$s$, $s$$10,000 total ($2,500 a year for four years)$s$, 10000, $s$Usually opens in October; the 2026 cycle was reviewed on a rolling basis until May 10, 2026$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Student with a disability$s$]::text[], $s$four_year$s$, null, $s$Must have a documented learning disability (an IEP or a formal evaluation). Must enroll full time in a bachelor's degree program.$s$, false),
  ($s$scholarship$s$, $s$Allegra Ford Thomas Scholarship$s$, $s$National Center for Learning Disabilities (NCLD)$s$, $s$https://ncld.org/?p=327$s$, $s$A two-year scholarship for high school seniors with a documented learning disability who will attend a community college, a vocational or technical program, or a program for students with disabilities.$s$, $s$Apply online through NCLD. Include your FAFSA information, one recommendation, three short answers, and proof of your learning disability as a PDF.$s$, $s$$5,000 total ($2,500 a year for two years)$s$, 5000, $s$Usually opens in October; the 2026 cycle was reviewed on a rolling basis until May 10, 2026$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, true, false, null::text[], array[$s$Student with a disability$s$]::text[], $s$technical$s$, null, $s$Must have a documented learning disability (an IEP or a formal evaluation). Must enroll in a two-year community college, a vocational or technical program, or a specialized program for students with disabilities.$s$, false),
  ($s$scholarship$s$, $s$National Federation of the Blind Scholarship Program$s$, $s$National Federation of the Blind$s$, $s$https://nfb.org/programs-services/scholarships-and-awards/scholarship-program$s$, $s$Thirty $8,000 scholarships each year for legally blind students who are starting or continuing college. Graduating seniors can apply.$s$, $s$Fill out the online application at nfb.org/scholarships, send the required documents, and set up an interview with your state NFB affiliate president.$s$, $s$$8,000 (30 awards)$s$, 8000, $s$Usually open Dec. 1 to March 31 (the 2026 cycle closed March 31, 2026)$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Student with a disability$s$]::text[], $s$any$s$, null, $s$Must be legally blind in both eyes, live in the U.S., D.C., or Puerto Rico, and be 18 by the start of the NFB National Convention in July. Must enroll in an accredited degree program; up to five awards go to part-time students. Finalists attend the NFB National Convention in person.$s$, false),
  ($s$scholarship$s$, $s$American Council of the Blind Scholarship Program$s$, $s$American Council of the Blind$s$, $s$https://acb.org/scholarships$s$, $s$Scholarships for legally blind students, including entering college freshmen and technical college students. They can pay for tuition, housing, and assistive technology.$s$, $s$Create an account at members.acb.org and apply online between Nov. 1, 2026 and Feb. 5, 2027. Include proof of legal blindness, your transcript, two recommendations, and your college acceptance.$s$, $s$$2,000 to $7,500$s$, 7500, $s$Feb. 5, 2027 at 11:59 p.m. CST (opens Nov. 1, 2026)$s$, $s$US$s$, '{12}'::int[], 3.0, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Student with a disability$s$]::text[], $s$any$s$, null, $s$Must be legally blind (20/200 or worse in the better eye with correction, or a visual field of 20 degrees or less). Must be a full-time student, or part-time while working at least 32 hours a week, and be involved in your school and community. A 3.0 GPA is required for most awards.$s$, false),
  ($s$scholarship$s$, $s$OAR Schwallie Family Scholarship$s$, $s$Organization for Autism Research (OAR)$s$, $s$https://researchautism.org/how-we-help/scholarships/$s$, $s$A $3,000 scholarship for students with an autism diagnosis who are going to a two- or four-year college full time.$s$, $s$Apply through OAR's online portal with proof of enrollment or acceptance and three short essays. You can add one optional recommendation.$s$, $s$$3,000$s$, 3000, $s$2027-28 application opens December 2026; the deadline is usually in April$s$, $s$US$s$, '{12}'::int[], null::numeric, null, null::int, null::int, null::int, false, false, null::text[], array[$s$Student with a disability$s$]::text[], $s$any$s$, null, $s$Must have an established autism diagnosis (DSM-IV or DSM-5). Must be accepted or enrolled full time (at least 6 credits) at an accredited U.S. two- or four-year college. Not for vocational or trade schools; OAR's Hussman Scholarship covers those. Finalists must send proof of diagnosis.$s$, false)
) as v(kind, name, sponsor, url, summary, how_to_apply, amount_text, amount_max, deadline_text, scope, grades, min_gpa, gpa_kind, min_sat, min_act, max_income, need_based, citizen_required, interests, groups, college_type, college, other_requirements, automatic)
